insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('rice-blast', 1, '稻熱病', 'Rice blast', 'Pyricularia oryzae（= Magnaporthe oryzae）', 'disease', array['rice']::text[], array['leaf', 'stem', 'flower']::text[], array['spots', 'stunting']::text[], '水稻最重要的真菌病害之一，可危害葉片、稻節及穗頸，穗稻熱會造成白穗與嚴重減產。', '["葉稻熱：葉片出現紡錘形（菱形）病斑，中央灰白色、外緣褐色，外圍常有黃色暈環。", "嚴重時病斑融合使葉片枯死，植株矮化、分蘗受阻（俗稱「坐蔸」）。", "穗稻熱：穗頸部變褐至黑褐色，養分無法輸送，造成白穗或稔實不良。", "節稻熱：稻稈節部變黑褐色，容易折斷。"]'::jsonb, '氣溫約 20–28°C、相對濕度高、連續陰雨或葉面長時間濕潤時容易發生；氮肥施用過量、植株過密的田區較嚴重。台灣一期作較常發生。', '["選用抗病品種，並使用健康種子（播種前進行種子消毒）。", "合理施用氮肥，避免過量及生育後期追施氮肥。", "插秧密度適中，保持田間通風。", "清除罹病稻草、田間及田埂雜草，減少初次感染源。"]'::jsonb, '["發病初期（葉片出現典型紡錘形病斑）即開始防治，並注意天氣預報，雨前雨後加強巡田。", "孕穗末期至齊穗期是防治穗稻熱的關鍵時期。", "依《植物保護手冊》選用登記藥劑，並輪替不同作用機制（FRAC 代碼）的藥劑，以延緩抗藥性。"]'::jsonb, '[{"k": "leaf", "shape": "grass", "p": "spindle", "cap": "葉片紡錘形病斑：中央灰白、外緣褐色、外圍黃暈"}, {"k": "plant", "state": "panicle", "cap": "穗頸變黑褐，形成白穗"}]'::jsonb, 'Magnaporthe oryzae', array['rice-sheath-blight', 'rice-bacterial-blight']::text[], '{}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('rice-sheath-blight', 2, '紋枯病', 'Rice sheath blight', 'Rhizoctonia solani AG1-IA', 'disease', array['rice']::text[], array['stem', 'leaf']::text[], array['spots', 'rot']::text[], '危害水稻葉鞘與葉片的土壤傳播性真菌病害，高溫多濕、密植田區容易大發生並造成倒伏。', '["近水面處的葉鞘先出現橢圓形、灰綠色水浸狀病斑。", "病斑擴大後中央灰白色、邊緣褐色，數個病斑相連呈雲紋狀。", "病斑由下往上蔓延到葉片，嚴重時全株枯死、倒伏。", "高濕時病斑表面可見白色菌絲及褐色、像油菜籽的菌核。"]'::jsonb, '高溫多濕（約 28–32°C），分蘗盛期至孕穗期最容易擴展；密植、氮肥過多、田間長期積水時嚴重。菌核可在土壤中存活多年。', '["合理密植，保持行株間通風。", "避免偏施氮肥，適量增施鉀肥。", "分蘗末期適時曬田，降低田間濕度。", "整地灌水後撈除浮在水面的菌核及殘體。"]'::jsonb, '["分蘗末期起定期檢查稻叢基部，罹病叢率明顯上升時即施藥。", "施藥時藥液必須噴到植株基部的葉鞘。", "可評估使用已登記的微生物製劑（例如枯草桿菌類），並依《植物保護手冊》輪用藥劑。"]'::jsonb, '[{"k": "stem", "p": "sheath", "cap": "近水面葉鞘的雲紋狀病斑"}]'::jsonb, 'rice sheath blight Rhizoctonia', array['rice-blast', 'brown-planthopper']::text[], '{}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('rice-bacterial-blight', 3, '白葉枯病', 'Rice bacterial leaf blight', 'Xanthomonas oryzae pv. oryzae', 'disease', array['rice']::text[], array['leaf', 'whole']::text[], array['yellowing', 'scorch', 'wilting']::text[], '細菌性病害，颱風、豪雨造成葉片傷口後容易大發生，葉片由葉尖、葉緣開始枯白。', '["葉尖或葉緣先出現黃綠色水浸狀條斑。", "病斑沿葉緣向下擴展，形成邊緣呈波浪狀的黃白色至灰白色枯斑。", "清晨在病斑上可見黃色露珠狀菌泥，乾後成為小顆粒。", "幼苗期感染可造成整株急性萎凋（Kresek 型）。"]'::jsonb, '颱風、豪雨過後葉片傷口多時最容易發生；溫度約 25–30°C、田間淹水、偏施氮肥時嚴重。台灣二期作颱風季較常見。', '["選用抗病品種。", "颱風前後避免施用氮肥。", "做好田區排水，避免灌溉水在病田與健田之間串流傳播。", "清除田埂上的寄主雜草（例如李氏禾）及罹病殘株。"]'::jsonb, '["颱風或豪雨過後、發病初期，施用已登記的細菌性病害藥劑（例如銅劑等）。", "葉片潮濕時避免進入田間操作，以免傳播病菌。"]'::jsonb, '[{"k": "leaf", "shape": "grass", "p": "margin-blight", "cap": "由葉尖、葉緣向下擴展的波浪狀黃白色枯斑"}]'::jsonb, 'Xanthomonas oryzae', array['rice-blast']::text[], '{}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('late-blight', 4, '晚疫病', 'Late blight', 'Phytophthora infestans', 'disease', array['tomato', 'potato']::text[], array['leaf', 'stem', 'fruit']::text[], array['spots', 'rot', 'powder']::text[], '冷涼高濕時爆發性很強的卵菌病害，條件適合時數天內就能讓整片田枯萎。', '["葉片出現不規則形、暗綠色水浸狀大斑，很快擴大並轉為褐黑色。", "潮濕時，病斑周緣的葉背長出一圈白色黴狀物。", "莖及葉柄出現黑褐色病斑，容易折斷。", "番茄果實出現油漬狀、表面粗糙的褐色硬斑，通常不軟腐。"]'::jsonb, '冷涼高濕：日夜溫約 15–22°C、相對濕度 90% 以上，有霧、露或連續降雨時最容易爆發。台灣多發生在冬、春季。', '["避免番茄與馬鈴薯連作或鄰近種植。", "使用健康種薯與種苗。", "加強通風，避免傍晚灑水使葉面整夜潮濕。", "設施栽培時注意通風除濕，發現病株立即清除。"]'::jsonb, '["低溫多雨期提前進行預防性施藥。", "發現病斑時立即施藥，並依天候縮短施藥間隔。", "輪用不同作用機制的登記藥劑（疫病菌容易產生抗藥性）。"]'::jsonb, '[{"k": "leaf", "p": "blight", "cap": "葉片水浸狀暗褐色大斑，周緣有白色黴"}, {"k": "fruit", "fruit": "tomato", "p": "greasy", "cap": "果實油漬狀褐色硬斑"}]'::jsonb, 'Phytophthora infestans tomato', array['early-blight', 'phytophthora-blight']::text[], '{}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('early-blight', 5, '早疫病', 'Early blight', 'Alternaria solani', 'disease', array['tomato', 'potato', 'eggplant', 'goldenberry']::text[], array['leaf', 'stem', 'fruit']::text[], array['spots', 'yellowing']::text[], '茄科常見的真菌病害，病斑具有明顯的同心輪紋（靶心狀），由下位老葉往上蔓延。', '["下位老葉先出現褐色圓形至不規則形病斑，具明顯的同心輪紋。", "病斑周圍黃化，嚴重時葉片由下往上枯黃、脫落。", "莖部出現橢圓形褐色輪紋斑。", "果實靠近果蒂處出現凹陷的黑褐色輪紋斑。"]'::jsonb, '溫暖（約 24–29°C）多濕、露水重時容易發生；植株生長勢弱、肥料不足或結果負擔重時較嚴重。', '["與非茄科作物輪作 2–3 年。", "平衡施肥，維持植株生長勢。", "摘除下位病葉並帶出田區。", "畦面敷蓋，減少雨水把土壤中的病菌濺到葉片上。"]'::jsonb, '["發病初期施用登記藥劑，注意噴到葉背及下位葉。", "輪替不同作用機制的藥劑。"]'::jsonb, '[{"k": "leaf", "p": "spots", "rings": true, "halo": true, "color": "#6b4423", "n": 6, "r": 8, "cap": "同心輪紋（靶心狀）褐斑，周圍黃化"}, {"k": "plant", "state": "old", "color": "#c9b84a", "cap": "由下位老葉開始往上蔓延"}]'::jsonb, 'Alternaria solani', array['late-blight', 'def-k']::text[], '{"tomato": "葉片同心輪紋斑；莖基部也會出現輪紋病斑（領腐），果實蒂部凹陷黑斑。", "potato": "葉片出現有稜角的同心輪紋斑；薯塊表面形成凹陷暗褐色斑。", "eggplant": "葉片出現褐色同心輪紋斑，多從下位葉開始。", "goldenberry": "老葉出現具同心輪紋的褐色病斑，宿萼（燈籠外殼）也可能出現褐斑，嚴重時大量落葉。"}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('bacterial-wilt', 6, '青枯病', 'Bacterial wilt', 'Ralstonia solanacearum', 'disease', array['tomato', 'pepper', 'eggplant', 'potato', 'goldenberry']::text[], array['whole', 'stem', 'root']::text[], array['wilting']::text[], '土壤傳播的細菌性維管束病害，植株會在葉片仍保持綠色時突然萎凋死亡。', '["初期植株頂端葉片在中午萎凋、傍晚恢復，數天後全株萎凋死亡。", "萎凋時葉片仍保持綠色，所以叫「青枯」。", "莖基部的維管束變褐色。", "簡易診斷：剪一段病莖插在清水中，數分鐘內可見乳白色菌泥從切口流出。"]'::jsonb, '高溫（約 30–35°C）多濕、土壤含水量高時最嚴重；連作田、根部被線蟲危害或中耕傷根時更容易感染。', '["嫁接抗病砧木（例如番茄嫁接於抗病茄子或番茄砧木）。", "與水稻輪作（水旱輪作）可大幅降低土中病菌。", "選擇排水良好的田區，採用高畦栽培。", "避免中耕傷根，田間工具使用後消毒。"]'::jsonb, '["目前沒有有效的化學治療藥劑。", "發現病株應立即連根拔除並帶離田區銷毀，病穴可撒施石灰。", "可評估太陽能消毒、浸水處理或已登記的生物製劑來處理土壤。"]'::jsonb, '[{"k": "plant", "state": "wilt", "cap": "全株萎凋，葉片仍呈綠色"}, {"k": "stem", "p": "ooze", "cap": "病莖切段插入清水，流出乳白色菌泥"}]'::jsonb, 'Ralstonia solanacearum', array['root-knot-nematode', 'phytophthora-blight']::text[], '{"tomato": "白天整株急速萎凋、夜間稍恢復，數日後枯死但葉片仍保持綠色。", "potato": "薯塊維管束環褐變，擠壓時芽眼或切面會流出乳白色菌泥。", "pepper": "植株突然萎凋，莖基部維管束褐變；高溫多濕季節最嚴重。", "eggplant": "植株從部分枝條開始萎凋，切開莖部可見褐變並溢出菌泥。", "goldenberry": "植株從頂梢或部分分枝開始萎凋，莖基部維管束褐變；高溫季節的連作田常成片發生。"}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('tylcv', 7, '番茄黃化捲葉病', 'Tomato yellow leaf curl disease', 'Tomato yellow leaf curl virus（TYLCV）等雙生病毒', 'disease', array['tomato']::text[], array['leaf', 'whole', 'flower']::text[], array['yellowing', 'curling', 'stunting', 'drop']::text[], '由銀葉粉蝨傳播的病毒病，早期感染幾乎不結果，損失可達 100%。', '["新葉變小，葉緣黃化並向上捲曲，呈杯狀。", "植株嚴重矮化，節間縮短。", "開花後大量落花，幾乎不結果。", "愈早感染損失愈大，後期感染則上部葉片出現症狀。"]'::jsonb, '由銀葉粉蝨（菸草粉蝨）以持續性方式傳播；夏秋季高溫乾燥、粉蝨族群高時最嚴重。', '["選用抗（耐）病品種。", "在防蟲網室內育苗，使用健康種苗。", "設施使用 50 目以上防蟲網。", "清除田間及周邊雜草與罹病殘株，避免與茄科、瓜類等粉蝨寄主連作或鄰作。"]'::jsonb, '["病毒病沒有藥劑可以治療，發現病株立即拔除，裝袋帶離田區銷毀。", "防治重點在媒介昆蟲銀葉粉蝨：黃色黏紙監測，並輪用登記殺蟲劑（見「銀葉粉蝨」）。"]'::jsonb, '[{"k": "leaf", "p": "curl", "cap": "新葉變小、葉緣黃化並向上捲曲"}, {"k": "plant", "state": "stunt", "cap": "植株矮化、節間縮短（右為健康株）"}]'::jsonb, 'tomato yellow leaf curl plant', array['silverleaf-whitefly']::text[], '{}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('cucurbit-downy-mildew', 8, '瓜類露菌病', 'Cucurbit downy mildew', 'Pseudoperonospora cubensis', 'disease', array['cucurbit']::text[], array['leaf']::text[], array['spots', 'yellowing', 'powder']::text[], '瓜類最常見的葉部病害之一，病斑受葉脈限制呈多角形，葉背有黴狀物。', '["葉表出現受葉脈限制的多角形黃色病斑。", "潮濕時，葉背對應位置長出灰紫色至黑色黴狀物。", "病斑後期轉為褐色乾枯，嚴重時整片葉枯死。", "通常由下位葉往上蔓延。"]'::jsonb, '高濕、葉面有水膜、日夜溫差大、氣溫約 15–25°C 時容易發生；春、秋雨季及露水重時嚴重。', '["選用耐病品種。", "適當株距，立支架並整枝，以利通風。", "採用滴灌，避免葉面長時間潮濕。", "摘除罹病老葉，帶出田區。"]'::jsonb, '["發病初期施用登記藥劑，預防性與治療性藥劑輪替使用。", "噴藥時一定要噴到葉背。"]'::jsonb, '[{"k": "leaf", "shape": "lobed", "p": "angular", "cap": "受葉脈限制的多角形黃斑"}]'::jsonb, 'Pseudoperonospora cubensis', array['powdery-mildew', 'grape-downy-mildew']::text[], '{}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('powdery-mildew', 9, '白粉病', 'Powdery mildew', 'Podosphaera spp.、Erysiphe spp.、Leveillula taurica 等', 'disease', array['cucurbit', 'strawberry', 'grape', 'mango', 'pepper', 'tomato', 'goldenberry', 'chrysanthemum']::text[], array['leaf', 'stem', 'fruit', 'flower']::text[], array['powder', 'yellowing', 'curling', 'drop']::text[], '葉面像撒了一層麵粉的真菌病害，不需下雨也能發生，乾季及設施栽培很常見。', '["葉面、葉背及嫩莖出現白色粉狀斑點，逐漸擴大覆蓋整片葉。", "葉片黃化、捲曲，提早枯落。", "果實受害時表面粗糙、著色不良或裂果。", "芒果、葡萄花穗受害會造成落花、結果不良。"]'::jsonb, '不需要葉面水膜就能發病；約 20–30°C、空氣濕度高但葉面乾燥、日照不足、通風差、植株過密時嚴重。', '["選用抗病品種。", "整枝修剪、合理密植，維持通風與日照。", "避免氮肥過量。", "摘除病葉，減少病原。"]'::jsonb, '["發病初期施用登記藥劑，例如硫磺劑等，並輪替不同作用機制。", "可評估使用已登記的礦物油、碳酸氫鉀或微生物製劑（例如枯草桿菌）等資材。", "高溫期使用硫磺劑要注意藥害。"]'::jsonb, '[{"k": "leaf", "shape": "lobed", "p": "powdery", "cap": "葉面白色粉狀黴斑"}]'::jsonb, 'powdery mildew cucurbit leaf', array['cucurbit-downy-mildew', 'anthracnose']::text[], '{"cucurbit": "葉片兩面布滿白粉，從下位葉開始向上蔓延，乾燥季節最嚴重。", "strawberry": "葉緣向上捲曲，葉背有白粉；果實表面長白粉、失去光澤。", "grape": "葉、新梢及果粒覆白粉，果粒表面形成網狀褐斑，容易裂果。", "mango": "花穗及幼果覆白粉，造成大量落花、落果。", "pepper": "葉背出現白粉、葉面相對位置黃化，嚴重時大量落葉。", "tomato": "葉面出現淡黃色斑，葉背或葉面長白粉，老葉先發生。", "goldenberry": "葉面及葉背出現白色粉狀黴斑，嚴重時葉片黃化提早掉落，影響果實充實。", "chrysanthemum": "葉片兩面長出白粉，多從下位葉開始；乾燥季節及設施栽培較常見，嚴重時葉片黃化枯萎。"}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('anthracnose', 10, '炭疽病', 'Anthracnose', 'Colletotrichum spp.', 'disease', array['mango', 'pepper', 'strawberry', 'banana', 'papaya', 'guava', 'grape']::text[], array['fruit', 'leaf', 'flower']::text[], array['spots', 'rot', 'drop']::text[], '高溫多雨時危害多種果實的真菌病害，常有潛伏感染，採收後才出現病斑。', '["葉片出現褐色至黑色不規則病斑，嫩葉扭曲變形。", "芒果花穗受害變黑枯死，造成落花。", "果實出現圓形、凹陷的黑褐色病斑，常有同心輪紋。", "潮濕時病斑上產生橙紅色（鮭肉色）黏稠孢子團。", "潛伏感染：果實採收後在後熟期才出現病斑。"]'::jsonb, '高溫多雨（約 25–30°C）時嚴重，病菌孢子靠雨水飛濺傳播，並由傷口侵入。', '["清園：剪除病枝病葉，清除落果。", "果實套袋（芒果、番石榴等）。", "辣椒、草莓可採設施避雨栽培。", "芒果可依品種條件進行採後熱水處理。"]'::jsonb, '["開花期、幼果期及降雨前後是防治關鍵期，施用登記藥劑並輪替。", "草莓育苗期加強防治，避免帶病苗定植到本田。"]'::jsonb, '[{"k": "fruit", "fruit": "mango", "p": "rot", "spores": true, "cap": "果實凹陷黑褐斑，潮濕時有橙紅色孢子團"}, {"k": "leaf", "p": "spots", "color": "#3b2a1a", "n": 5, "r": 9, "irregular": true, "cap": "葉片不規則黑褐色病斑"}]'::jsonb, 'mango anthracnose', array['gray-mold', 'powdery-mildew']::text[], '{"mango": "果實成熟後出現黑色凹陷斑並擴大腐爛；花穗變黑枯死，雨季開花期最嚴重。", "pepper": "果實上出現水浸狀凹陷圓斑，上有同心輪紋排列的黑點或橙紅色孢子堆。", "strawberry": "走蔓及葉柄出現黑褐色凹陷病斑，侵入冠部時整株萎凋（炭疽冠腐），育苗期最常見。", "banana": "成熟果皮出現黑褐色凹陷斑，催熟後迅速擴大，果柄也會腐爛。", "papaya": "成熟果實出現水浸狀圓形凹陷斑，中央有橙紅色孢子堆。", "guava": "果實出現黑褐色凹陷斑並腐爛，嫩梢可能枯死。", "grape": "成熟果粒出現褐色凹陷斑，上有橙紅色孢子堆（晚腐病），果粒乾縮。"}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('citrus-hlb', 11, '柑橘黃龍病', 'Citrus greening (Huanglongbing, HLB)', 'Candidatus Liberibacter asiaticus', 'disease', array['citrus']::text[], array['leaf', 'fruit', 'whole']::text[], array['yellowing', 'mosaic', 'stunting', 'drop']::text[], '由柑橘木蝨傳播的韌皮部細菌病害，目前無藥可治，是柑橘產業最嚴重的威脅。', '["葉片出現左右不對稱的黃綠斑駁（缺素症通常左右對稱，可藉此區別）。", "部分枝條新梢黃化（黃梢）。", "葉片變小、直立，類似缺鋅症狀。", "果實小、畸形，果蒂端先著色而果頂仍綠（倒吊色、紅鼻果），種子發育不良，果汁味苦。", "樹勢逐年衰退，最後死亡。"]'::jsonb, '由柑橘木蝨傳播，也可經由帶病苗木或接穗傳播；新梢期木蝨族群高時傳播最快。', '["種植經檢定的無病健康苗。", "新梢期加強防治柑橘木蝨。", "移除果園周邊的七里香（月橘），它是木蝨的重要寄主。", "定期巡園，疑似病株送農業改良場或植物醫師檢測確診。"]'::jsonb, '["沒有藥劑可以治療。確診植株應挖除，以免成為傳染源。", "全區共同防治柑橘木蝨（見「柑橘木蝨」）。"]'::jsonb, '[{"k": "leaf", "p": "blotchy", "cap": "葉片左右不對稱的黃綠斑駁"}, {"k": "fruit", "fruit": "citrus", "p": "hlb", "cap": "果蒂端轉色、果頂仍綠（倒吊色）"}]'::jsonb, 'citrus greening huanglongbing', array['asian-citrus-psyllid', 'def-zn', 'citrus-canker']::text[], '{}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('citrus-canker', 12, '柑橘潰瘍病', 'Citrus canker', 'Xanthomonas citri subsp. citri', 'disease', array['citrus']::text[], array['leaf', 'fruit', 'stem']::text[], array['spots', 'cracking', 'drop']::text[], '細菌性病害，在葉、枝、果上形成隆起粗糙的木栓化病斑，影響果實外觀與商品價值。', '["葉、枝、果先出現黃色小點，後變成隆起、木栓化、表面粗糙的褐色病斑。", "病斑周圍有黃色暈環，葉片正反兩面都會突起。", "果實病斑只在果皮，但嚴重影響外觀。", "嚴重時落葉、落果。"]'::jsonb, '高溫多雨、颱風後傷口多時容易發生；柑橘潛葉蛾的危害會增加傷口而加重病情。檸檬、葡萄柚、文旦較感病。', '["設置防風林或防風網，減少風傷。", "新梢期防治柑橘潛葉蛾。", "剪除病枝病葉並清園，修剪工具使用後消毒。"]'::jsonb, '["新梢萌發期及颱風、豪雨前後施用登記藥劑（例如銅劑）。", "高溫期使用銅劑要注意藥害。"]'::jsonb, '[{"k": "leaf", "p": "spots", "raised": true, "halo": true, "color": "#9c7442", "n": 8, "r": 5, "cap": "隆起木栓化病斑，周圍黃暈"}, {"k": "fruit", "fruit": "citrus", "p": "canker", "cap": "果皮上粗糙突起的褐斑"}]'::jsonb, 'citrus canker', array['citrus-hlb']::text[], '{}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('banana-fusarium-wilt', 13, '香蕉黃葉病', 'Fusarium wilt of banana (Panama disease)', 'Fusarium oxysporum f. sp. cubense（熱帶第四生理小種 TR4）', 'disease', array['banana']::text[], array['leaf', 'stem', 'root', 'whole']::text[], array['yellowing', 'wilting', 'cracking']::text[], '土壤傳播的維管束病害，病菌可在土中存活數十年，是香蕉產業的毀滅性病害。', '["下位老葉由葉緣開始黃化，逐漸往上位葉發展。", "葉柄基部折斷，枯葉下垂包圍假莖，呈裙狀。", "假莖基部縱向裂開。", "縱切或橫切假莖、球莖，可見維管束呈紅褐色至黑褐色。"]'::jsonb, '經由帶菌吸芽、土壤、農機具、灌溉水傳播；病菌的厚膜孢子可在土中存活數十年。酸性、排水不良的土壤較嚴重。', '["使用組織培養的健康種苗。", "選用抗（耐）病品種，例如台灣香蕉研究所選育的「寶島蕉」等。", "可與水稻輪作。", "農機具、鞋靴進出田區前清洗消毒，避免帶土跨區。", "調整土壤 pH、增施有機質。"]'::jsonb, '["沒有藥劑可以治療。", "病株就地處理（例如注射除草劑殺株或挖除），避免移動病土。", "病區不要再種植感病品種。"]'::jsonb, '[{"k": "plant", "state": "skirt", "cap": "老葉由葉緣黃化，葉柄折斷下垂成裙狀"}, {"k": "stem", "p": "vascular", "cap": "假莖橫切面，維管束呈紅褐色"}]'::jsonb, 'Fusarium oxysporum cubense banana', array['bacterial-wilt']::text[], '{}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('gray-mold', 14, '灰黴病', 'Gray mold', 'Botrytis cinerea', 'disease', array['strawberry', 'tomato', 'grape', 'goldenberry', 'chrysanthemum']::text[], array['fruit', 'flower', 'leaf']::text[], array['rot', 'powder']::text[], '低溫高濕時危害花與果實的真菌病害，果實軟腐並長出灰色毛絨狀黴層。', '["花瓣、花萼先受害變褐。", "果實出現淡褐色水浸狀病斑，很快軟腐。", "病部表面長出灰色毛絨狀黴層，一碰就飛散出孢子。", "番茄果實可見白色小環狀的「鬼斑」。"]'::jsonb, '低溫（約 15–23°C）高濕、連續陰雨、設施通風不良時嚴重；多發生於冬、春季。', '["適當密植，摘除老葉、病果。", "敷蓋塑膠布，避免果實接觸土壤。", "設施加強通風除濕。", "採收及管理時避免果實受傷。"]'::jsonb, '["開花期起預防性施用登記藥劑，並輪替不同作用機制（灰黴病菌很容易產生抗藥性）。", "病果裝袋帶離田區。"]'::jsonb, '[{"k": "fruit", "fruit": "strawberry", "p": "mold", "cap": "花或果實軟腐並長出灰色黴層"}]'::jsonb, 'Botrytis cinerea strawberry', array['anthracnose']::text[], '{"strawberry": "果實出現褐色軟腐並覆灰色黴層，多從花萼端或接觸土面處開始。", "tomato": "果實長灰黴，或出現白色小圈的「鬼斑」；莖部病斑環繞時，上方枝葉萎凋。", "grape": "果房內果粒褐腐並覆灰黴，成熟期遇雨最嚴重。", "goldenberry": "多由凋謝花瓣或宿萼侵入，宿萼內的果實腐爛並長出灰色黴層；採收期多雨、宿萼不易乾燥時最嚴重。", "chrysanthemum": "開花期遇冷涼多濕，花瓣出現褐色水浸狀斑並長出灰黴，花朵腐爛；採收後未及時乾燥也會發生。"}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('crucifer-black-rot', 15, '十字花科黑腐病', 'Black rot of crucifers', 'Xanthomonas campestris pv. campestris', 'disease', array['crucifer']::text[], array['leaf', 'stem']::text[], array['yellowing', 'spots', 'rot']::text[], '種子可帶菌的細菌性病害，典型症狀是葉緣的 V 字形黃化病斑。', '["葉緣出現 V 字形黃化病斑，尖端指向中肋。", "病斑內的葉脈變黑。", "病斑擴大後葉片乾枯。", "莖部維管束變黑，嚴重時結球腐爛。"]'::jsonb, '種子帶菌，病菌由葉緣水孔及傷口侵入；高溫多濕（約 25–30°C）、颱風豪雨後嚴重。', '["使用無病種子，或進行溫湯浸種（例如約 50°C 熱水浸 25–30 分鐘，依作物種類調整）。", "與非十字花科作物輪作 2–3 年。", "清除罹病殘株。", "避免噴灌。"]'::jsonb, '["發病初期施用登記藥劑（例如銅劑）。", "雨後及颱風後加強防治。"]'::jsonb, '[{"k": "leaf", "p": "v-lesion", "cap": "葉緣 V 字形黃化病斑，葉脈變黑"}]'::jsonb, 'Xanthomonas campestris black rot cabbage', array['clubroot', 'diamondback-moth']::text[], '{}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('clubroot', 16, '根瘤病', 'Clubroot', 'Plasmodiophora brassicae', 'disease', array['crucifer']::text[], array['root', 'whole']::text[], array['wilting', 'galls', 'stunting', 'yellowing']::text[], '十字花科在酸性土壤中常見的根部病害，根部長出大型腫瘤，休眠孢子可在土中存活 10 年以上。', '["白天萎凋，早晚恢復。", "生長遲緩，葉片黃化。", "拔起植株可見根部長出大小不一的紡錘形或塊狀腫瘤。", "後期腫瘤腐爛。"]'::jsonb, '酸性土壤（pH 低於 6.5）、排水不良、土溫約 20–25°C 時容易發生；休眠孢子可在土中存活 10 年以上。', '["施用石灰資材，將土壤 pH 調整到約 7.2。", "選用抗病品種。", "與非十字花科作物長期輪作。", "使用無病苗床土，並維持田區排水良好。", "病根不要留在田間。"]'::jsonb, '["定植前依《植物保護手冊》以登記藥劑進行土壤處理。", "病株連根拔除並帶離田區。"]'::jsonb, '[{"k": "roots", "type": "club", "cap": "根部紡錘形或塊狀腫瘤"}, {"k": "plant", "state": "wilt", "cap": "白天萎凋、生長遲緩"}]'::jsonb, 'Plasmodiophora brassicae clubroot', array['root-knot-nematode', 'crucifer-black-rot']::text[], '{}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('papaya-ringspot', 17, '木瓜輪點病', 'Papaya ringspot', 'Papaya ringspot virus（PRSV）', 'disease', array['papaya', 'cucurbit']::text[], array['leaf', 'fruit', 'stem']::text[], array['mosaic', 'spots', 'curling', 'stunting']::text[], '由蚜蟲傳播的病毒病，造成木瓜葉片嵌紋、果實輪點，是木瓜栽培最主要的限制因子。', '["新葉出現黃綠嵌紋，皺縮變形，嚴重時葉片呈絲狀。", "葉柄與莖幹出現水浸狀、油漬狀條斑。", "果實表面出現同心圓狀的輪點。", "植株生長衰弱，產量與品質大幅下降。"]'::jsonb, '由蚜蟲以非持續性方式傳播（蚜蟲短時間試吸就能傳毒）；鄰近罹病株或瓜類作物時容易感染。', '["網室栽培，隔絕蚜蟲。", "使用健康種苗。", "早期發現病株立即剷除。", "與瓜類田保持距離，並可種植耐病品種。"]'::jsonb, '["沒有藥劑可以治療，以網室栽培與剷除病株為主。", "蚜蟲是以非持續性方式傳毒，噴殺蟲劑防止傳毒的效果有限。"]'::jsonb, '[{"k": "leaf", "shape": "lobed", "p": "mosaic", "cap": "新葉黃綠嵌紋、皺縮"}, {"k": "fruit", "fruit": "papaya", "p": "ringspot", "cap": "果實表面同心輪點"}]'::jsonb, 'papaya ringspot virus', array['aphids']::text[], '{}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('phytophthora-blight', 18, '疫病（辣椒、瓜類）', 'Phytophthora blight', 'Phytophthora capsici', 'disease', array['pepper', 'cucurbit', 'eggplant']::text[], array['stem', 'root', 'fruit', 'leaf']::text[], array['wilting', 'rot', 'powder']::text[], '雨季常見的卵菌病害，病菌隨水傳播，莖基部受害造成全株萎凋，果實軟腐長白黴。', '["莖基部出現暗褐色至黑色水浸狀病斑，環繞莖部後全株萎凋死亡。", "果實出現水浸狀軟腐，表面長出白色黴狀物。", "葉片出現暗綠色水浸狀大斑。"]'::jsonb, '高溫多雨、土壤積水時嚴重；病菌的游走子隨水傳播。連作田較嚴重。', '["高畦栽培並加強排水。", "敷蓋塑膠布，減少泥水濺起。", "與非寄主作物輪作，避免淹灌。"]'::jsonb, '["雨季前預防性施用登記藥劑（可灌注莖基部及噴施植株）。", "病株拔除並帶離田區。"]'::jsonb, '[{"k": "stem", "p": "collar", "cap": "莖基部黑褐色病斑，全株萎凋"}, {"k": "fruit", "fruit": "pepper", "p": "whitemold", "cap": "果實水浸狀軟腐並長白黴"}]'::jsonb, 'Phytophthora capsici', array['late-blight', 'bacterial-wilt']::text[], '{"pepper": "莖基部黑褐色縊縮、全株萎凋；果實出現水浸狀軟腐並長白黴。", "cucurbit": "莖蔓基部水浸狀縊縮；接觸地面的果實軟腐並長白黴。", "eggplant": "果實出現水浸狀褐色病斑並長白黴，莖基部褐變。"}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('corn-southern-rust', 19, '玉米南方銹病', 'Southern rust of corn', 'Puccinia polysora', 'disease', array['corn']::text[], array['leaf']::text[], array['spots', 'yellowing']::text[], '高溫高濕時發生的真菌病害，葉片上密布橙色粉狀孢子堆。', '["葉片表面出現密集、圓形至橢圓形、橙黃色至橙紅色的小型突起孢子堆。", "表皮破裂後散出鐵銹色粉末。", "嚴重時葉片提早乾枯，籽粒不飽滿。"]'::jsonb, '高溫（約 27°C）高濕時容易發生，多見於夏秋作；孢子可隨風遠距離傳播。', '["選用抗病品種。", "適期種植。", "清除罹病殘株。"]'::jsonb, '["發病初期施用登記藥劑。"]'::jsonb, '[{"k": "leaf", "shape": "grass", "p": "rust", "cap": "密集的橙色突起孢子堆"}]'::jsonb, 'Puccinia polysora', array['fall-armyworm']::text[], '{}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('grape-downy-mildew', 20, '葡萄露菌病', 'Grape downy mildew', 'Plasmopara viticola', 'disease', array['grape']::text[], array['leaf', 'fruit', 'flower']::text[], array['spots', 'yellowing', 'powder', 'rot']::text[], '多雨時危害葡萄葉片、花穗與幼果的卵菌病害，葉表出現油斑、葉背長白色霜黴。', '["葉表出現淡黃色、半透明的油漬狀斑（油斑）。", "葉背對應位置長出白色霜狀黴層。", "花穗、幼果受害變褐萎縮，並長出白黴。", "較大的果粒變褐皺縮；嚴重時落葉。"]'::jsonb, '多雨潮濕、葉面濕潤時間長時容易發生；春季開花至幼果期及秋季較嚴重。', '["設施避雨栽培。", "修剪改善通風。", "清除落葉及病枝。"]'::jsonb, '["開花前後及雨季預防性施藥，輪用不同作用機制的登記藥劑。"]'::jsonb, '[{"k": "leaf", "shape": "lobed", "p": "oilspot", "cap": "葉表黃色油斑，葉背白色霜黴"}, {"k": "fruit", "fruit": "grape", "p": "downy", "cap": "幼果變褐皺縮並長白黴"}]'::jsonb, 'Plasmopara viticola', array['cucurbit-downy-mildew', 'powdery-mildew']::text[], '{}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('goldenberry-fusarium-wilt', 21, '燈籠果萎凋病', 'Goldenberry Fusarium wilt', 'Fusarium oxysporum f. sp. physali', 'disease', array['goldenberry']::text[], array['whole', 'stem', 'root']::text[], array['wilting', 'yellowing']::text[], '土壤傳播的真菌性維管束病害，是燈籠果最重要的病害之一，植株由下而上黃化、萎凋死亡。', '["下位葉先黃化，常只出現在植株一側或部分分枝，再逐漸向上擴展。", "植株中午萎凋、早晚恢復，後期全株萎凋枯死。", "剖開莖基部可見維管束褐變；與青枯病不同，病莖插入清水不會流出乳白色菌泥。", "果實變小、提早轉色或掉落。"]'::jsonb, '土溫約 25–30°C、土壤偏酸、排水不良時較常發生。病菌以厚膜孢子在土中存活多年，可藉病苗、帶菌土壤、灌溉水與農具傳播；連作田或根部受線蟲危害時更嚴重。', '["使用健康種苗，以無病介質育苗。", "避免連作，與水稻或非茄科作物輪作。", "採用高畦、保持排水良好；酸性土壤可施用石灰調整酸鹼值。", "防治根瘤線蟲、避免中耕傷根，農具使用後消毒。"]'::jsonb, '["發現病株立即連根拔除，帶離田區銷毀。", "目前沒有有效的治療藥劑，可評估太陽能消毒、浸水處理或已登記的生物製劑（如木黴菌）處理土壤。", "燈籠果的登記藥劑有限，用藥前請先查詢《植物保護手冊》確認已登記於燈籠果。"]'::jsonb, '[{"k": "plant", "state": "old", "cap": "下位葉先黃化，再向上擴展並萎凋"}, {"k": "stem", "p": "vascular", "cap": "莖基部橫切面，維管束褐變"}]'::jsonb, 'Fusarium wilt Physalis peruviana', array['bacterial-wilt', 'root-knot-nematode']::text[], '{}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('chrysanthemum-white-rust', 22, '菊花白銹病', 'Chrysanthemum white rust', 'Puccinia horiana', 'disease', array['chrysanthemum']::text[], array['leaf']::text[], array['spots', 'yellowing']::text[], '菊花最重要的病害之一，葉背長出隆起的白色至淡褐色孢子堆，冷涼多濕時傳播快速。', '["葉面出現淡黃綠色小斑點，稍微凹陷。", "斑點對應的葉背長出隆起、蠟狀的白色至淡粉紅色膿疱（孢子堆），老化後轉為淡褐色。", "病斑多時葉片黃化、捲曲枯死，由下位葉往上蔓延。", "嚴重時影響開花數量與花朵品質。"]'::jsonb, '氣溫約 17–24°C、高濕或葉面長時間濕潤時容易發生，孢子需要水膜才能發芽。主要靠帶病的母株與插穗遠距離傳播，田間則藉風雨擴散。', '["使用健康母株與插穗，不從發病田區取穗。", "適當株距、保持通風，避免傍晚灑水使葉面長時間潮濕。", "定期巡田，摘除病葉並帶離田區銷毀。", "採收後清除殘株，減少下一期的感染源。"]'::jsonb, '["發病初期即開始防治，噴藥時著重葉背。", "依《植物保護手冊》選用登記藥劑，並輪替不同作用機制（FRAC 代碼）的藥劑。", "杭菊為食用花茶，用藥前請查詢《植物保護手冊》確認藥劑已登記於杭菊（菊花），並嚴守安全採收期。"]'::jsonb, '[{"k": "leaf", "shape": "chrys", "p": "whiterust", "cap": "葉面淡黃斑點，葉背長出白色隆起孢子堆"}]'::jsonb, 'Puccinia horiana', array['chrysanthemum-leaf-spot', 'powdery-mildew']::text[], '{}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('chrysanthemum-leaf-spot', 23, '菊花葉斑病（黑斑病）', 'Chrysanthemum Septoria leaf spot', 'Septoria chrysanthemella、Septoria obesa', 'disease', array['chrysanthemum']::text[], array['leaf']::text[], array['spots', 'yellowing']::text[], '杭菊常見的真菌性葉部病害，下位葉出現黑褐色病斑，多雨季節由下往上擴展，造成大量枯葉。', '["下位葉先出現圓形至不規則形病斑，初期褐色，後轉為黑褐色，周圍常有黃暈。", "病斑上可見細小黑點（柄子殼）。", "病斑擴大癒合後葉片黃化枯死，枯葉常掛在莖上不脫落，並由下往上蔓延。", "嚴重時植株只剩上部少數葉片，影響開花與產量。"]'::jsonb, '溫暖多雨時最嚴重，梅雨及颱風季節容易大發生。孢子藉雨水飛濺傳播，密植、通風不良及靠近地面的葉片容易發病；病菌可在罹病殘株上存活。', '["使用健康插穗。", "畦面敷蓋，減少雨水把土中病菌濺到葉片上。", "適當株距，摘除下位老葉與病葉，保持通風。", "採收後清園，避免連作。"]'::jsonb, '["梅雨季前及發病初期開始防治。", "依《植物保護手冊》選用登記藥劑，並輪替不同作用機制（FRAC 代碼）的藥劑。", "杭菊為食用花茶，用藥前請查詢《植物保護手冊》確認藥劑已登記於杭菊（菊花），並嚴守安全採收期。"]'::jsonb, '[{"k": "leaf", "shape": "chrys", "p": "spots", "color": "#2e2218", "n": 7, "r": 7, "halo": true, "irregular": true, "cap": "黑褐色病斑，周圍有黃暈，由下位葉開始"}]'::jsonb, 'Septoria chrysanthemi leaf spot', array['chrysanthemum-white-rust', 'early-blight']::text[], '{}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('coconut-gray-blight', 24, '椰子灰斑病', 'Coconut gray leaf blight', 'Pestalotiopsis palmarum（= Pestalotia palmarum）', 'disease', array['coconut']::text[], array['leaf']::text[], array['spots', 'scorch']::text[], '椰子常見的葉部病害，老葉小葉上出現中央灰白、邊緣褐色的病斑，嚴重時葉片大面積枯乾。', '["小葉初期出現黃色小斑點，擴大後成為長橢圓形病斑，中央灰白色、邊緣深褐色。", "病斑上散生黑色小點（分生孢子盤）。", "病斑癒合後，小葉由葉尖往內枯乾，外觀像葉枯。", "多發生在下位老葉；缺鉀、生長衰弱的植株較嚴重。"]'::jsonb, '高溫多濕時容易發生，孢子藉風雨傳播，由傷口或衰弱組織侵入；營養不良（尤其缺鉀）、排水不良的植株受害較嚴重。', '["均衡施肥，特別注意補充鉀肥。", "剪除嚴重罹病的老葉，帶離田區銷毀。", "改善排水，避免植株過密。"]'::jsonb, '["發病初期依《植物保護手冊》選用登記藥劑，並輪替不同作用機制（FRAC 代碼）的藥劑。", "椰子的登記藥劑有限，用藥前請先查詢《植物保護手冊》確認已登記於椰子，並遵守安全採收期。"]'::jsonb, '[{"k": "leaf", "shape": "grass", "p": "spots", "color": "#cfcabb", "edge": "#5a3a1e", "n": 7, "r": 5, "irregular": true, "cap": "小葉上中央灰白、邊緣深褐色的病斑"}]'::jsonb, 'Pestalotiopsis palmarum', array['def-k', 'coconut-bud-rot']::text[], '{}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('coconut-bud-rot', 25, '芽腐病（心腐病）', 'Coconut bud rot', 'Phytophthora palmivora', 'disease', array['coconut']::text[], array['whole', 'leaf']::text[], array['rot', 'wilting', 'yellowing']::text[], '危害椰子生長點的卵菌病害，心葉腐爛後植株無法再抽新葉，延誤處理會造成整株死亡。', '["最早是中央未展開的心葉褪色、萎凋，輕拉即可拔起。", "心葉基部與生長點組織軟腐，散發惡臭。", "外圍葉片由內向外逐漸黃化下垂，未成熟的果實掉落。", "生長點死亡後樹冠只剩老葉，最後全株死亡。"]'::jsonb, '多雨、高濕季節及颱風過後容易發生；病菌隨雨水飛濺傳播，從生長點附近侵入，植株受傷或樹冠積水時更嚴重。', '["颱風、豪雨過後加強巡查心葉。", "改善園區排水，避免樹冠內長期積水。", "及早清除病株，減少感染源。"]'::jsonb, '["初期發現時，切除腐爛組織至健康部位，再依《植物保護手冊》以登記藥劑處理傷口與生長點周圍。", "生長點已腐爛的植株無法恢復，應砍除銷毀。", "椰子的登記藥劑有限，用藥前請先查詢《植物保護手冊》確認已登記於椰子，並遵守安全採收期。"]'::jsonb, '[{"k": "plant", "state": "crowndie", "cap": "中央心葉褐變腐爛、下垂"}]'::jsonb, 'Phytophthora palmivora coconut bud rot', array['red-palm-weevil', 'coconut-gray-blight']::text[], '{}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('spodoptera-litura', 26, '斜紋夜蛾（斜紋夜盜蟲）', 'Tobacco cutworm', 'Spodoptera litura', 'pest', array['crucifer', 'tomato', 'pepper', 'eggplant', 'cucurbit', 'strawberry', 'corn', 'potato', 'goldenberry', 'chrysanthemum']::text[], array['leaf', 'fruit']::text[], array['holes', 'insects']::text[], '寄主範圍極廣的夜蛾類害蟲，幼蟲夜間大量取食葉片與果實。', '["幼蟲體色變化大（灰綠色至黑褐色），各節背側有一對黑色半月形斑紋。", "初齡幼蟲群聚在葉背啃食葉肉，留下透明的表皮（窗狀）。", "三齡後分散，夜間取食，造成葉片大缺刻，嚴重時只剩葉脈。", "也會蛀食果實。卵成塊產下，表面覆蓋黃褐色鱗毛。"]'::jsonb, '全年都會發生，夏秋高溫期族群最高；寄主範圍極廣。', '["利用性費洛蒙誘蟲盒監測，並大量誘殺雄蛾。", "摘除卵塊及群聚初齡幼蟲的葉片。", "清除田間雜草，設施可使用防蟲網。"]'::jsonb, '["幼蟲初齡時防治效果最好。", "生物製劑：蘇力菌（Bt）、斜紋夜蛾核多角體病毒（SlNPV）。", "化學藥劑輪替不同作用機制（IRAC 代碼）以避免抗藥性；幼蟲夜間活動，傍晚施藥效果較好。"]'::jsonb, '[{"k": "bug", "t": "caterpillar", "color": "#5b5a3c", "marks": true, "cap": "幼蟲各節背側有黑色半月紋"}, {"k": "leaf", "p": "holes", "style": "chew", "cap": "葉片大缺刻，嚴重時只剩葉脈"}]'::jsonb, 'Spodoptera litura larva', array['fall-armyworm', 'diamondback-moth']::text[], '{"crucifer": "幼蟲群聚葉背啃食成薄膜狀，長大後分散，把葉片吃成大缺刻。", "strawberry": "幼蟲夜間取食葉片與果實，果實表面出現不規則食痕。", "corn": "幼蟲鑽食心葉與果穗，心葉展開後可見成排孔洞與蟲糞。", "goldenberry": "幼蟲取食葉片造成大缺刻，也會咬破宿萼取食果實。", "chrysanthemum": "幼蟲夜間取食葉片與花朵，造成葉片缺刻及花朵殘缺。"}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('helicoverpa-armigera', 27, '番茄夜蛾（棉鈴蟲）', 'Cotton bollworm (tomato fruitworm)', 'Helicoverpa armigera', 'pest', array['goldenberry', 'tomato', 'pepper', 'eggplant', 'corn', 'chrysanthemum']::text[], array['fruit', 'flower', 'leaf']::text[], array['holes', 'insects']::text[], '雜食性夜蛾，幼蟲鑽食花蕾與果實，蛀孔處有蟲糞並引起腐爛，一隻幼蟲可連續危害多個果實。', '["幼蟲體色變化大（綠、黃褐至暗褐），體側有淡色縱帶，體表有小刺毛。", "幼齡幼蟲取食嫩葉與花蕾，之後鑽入果實取食，果實上留下圓形蛀孔與蟲糞。", "被害果實容易腐爛、掉落；幼蟲常轉移危害多個果實。", "成蟲為黃褐色中型蛾，前翅中央有腎形斑。"]'::jsonb, '全年可見，春、秋兩季密度較高；寄主範圍廣，鄰近玉米、番茄等田區時容易移入。', '["摘除被害果與落果並銷毀，減少田間蟲源。", "利用性費洛蒙誘蟲器監測及誘殺成蟲。", "設置防蟲網，並保護寄生蜂等天敵。"]'::jsonb, '["幼蟲鑽入果實後藥劑難以接觸，應在卵孵化至幼齡幼蟲期防治。", "可使用已登記的蘇力菌等生物性藥劑；依《植物保護手冊》選用登記藥劑，並輪替不同作用機制（IRAC 代碼）的藥劑。"]'::jsonb, '[{"k": "bug", "t": "caterpillar", "color": "#7d8c3e", "cap": "幼蟲體側有淡色縱帶，體色多變"}, {"k": "fruit", "fruit": "tomato", "p": "bore", "cap": "果實或花朵上的蛀孔與蟲糞"}]'::jsonb, 'Helicoverpa armigera larva', array['spodoptera-litura', 'fall-armyworm']::text[], '{"goldenberry": "幼蟲咬破宿萼鑽入取食果實，宿萼外常只看到小孔，剝開才發現果實已被蛀食腐爛。", "tomato": "青果、紅果都會被蛀食，蛀孔附近有蟲糞，果實容易腐爛。", "pepper": "幼蟲從果蒂附近鑽入果實內部取食，被害果腐爛掉落。", "corn": "幼蟲取食雌穗花絲與果穗頂端的籽粒。", "chrysanthemum": "幼蟲鑽食花苞與花朵，可見蛀孔與蟲糞，直接造成採收量損失。"}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('diamondback-moth', 28, '小菜蛾', 'Diamondback moth', 'Plutella xylostella', 'pest', array['crucifer']::text[], array['leaf']::text[], array['holes', 'insects']::text[], '十字花科蔬菜最重要的害蟲之一，對許多藥劑很容易產生抗藥性。', '["幼蟲淡綠色、紡錘形，受驚擾時劇烈扭動並吐絲下垂。", "幼蟲啃食葉肉，留下透明表皮形成「天窗」，長大後咬成孔洞。", "危害心葉時會影響結球。", "成蟲停棲時，背部可見淡色菱形紋。"]'::jsonb, '冷涼乾燥的秋冬至春季族群較多；對多種藥劑容易產生抗藥性。', '["利用性費洛蒙誘殺雄蛾。", "與非十字花科作物輪作，收穫後清除殘株。", "網室栽培。", "噴灌（灑水）可干擾成蟲並沖落幼蟲。"]'::jsonb, '["輪用不同作用機制（IRAC 代碼）的登記藥劑。", "使用蘇力菌（Bt）等生物製劑。", "保護天敵，例如小菜蛾絨繭蜂。"]'::jsonb, '[{"k": "bug", "t": "caterpillar", "color": "#7dbb4a", "spindle": true, "cap": "幼蟲淡綠色、紡錘形"}, {"k": "leaf", "p": "holes", "style": "window", "cap": "啃食葉肉留下透明「天窗」"}, {"k": "bug", "t": "moth", "cap": "成蟲停棲時背部菱形紋"}]'::jsonb, 'Plutella xylostella', array['spodoptera-litura', 'flea-beetle']::text[], '{}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('aphids', 29, '蚜蟲', 'Aphids', 'Aphis gossypii、Myzus persicae 等', 'pest', array['cucurbit', 'pepper', 'eggplant', 'tomato', 'crucifer', 'citrus', 'papaya', 'strawberry', 'potato', 'goldenberry', 'chrysanthemum']::text[], array['leaf', 'stem', 'flower']::text[], array['curling', 'honeydew', 'insects', 'stunting']::text[], '群聚在嫩芽刺吸汁液的小型害蟲，繁殖極快，並會傳播多種病毒病。', '["群聚在嫩葉、嫩梢及葉背，體長約 1–2 mm，有綠、黃、黑等顏色；腹部末端有一對腹管。", "新葉捲曲皺縮，生長停滯。", "分泌蜜露，誘發煤煙病，葉面變黑。", "傳播多種病毒病，例如木瓜輪點病毒、胡瓜嵌紋病毒。"]'::jsonb, '冷涼乾燥季節（秋至春）族群增加很快；以孤雌胎生方式繁殖，速度驚人。氮肥過多時嚴重。', '["黃色黏紙監測有翅蚜。", "銀色塑膠布敷蓋可驅避有翅蚜。", "使用防蟲網。", "保護天敵（瓢蟲、草蛉、寄生蜂），並避免偏施氮肥。"]'::jsonb, '["少量發生時，可用水柱沖洗，或使用已登記的窄域油、皂類資材。", "族群高時輪用登記藥劑，並噴到葉背與心葉。"]'::jsonb, '[{"k": "bug", "t": "aphid", "color": "#86b84a", "cap": "群聚嫩葉葉背；腹部末端有一對腹管"}, {"k": "leaf", "p": "sooty", "cap": "蜜露誘發煤煙病，葉面變黑"}]'::jsonb, 'Aphis gossypii', array['papaya-ringspot', 'silverleaf-whitefly', 'scale-insects']::text[], '{"crucifer": "群聚葉背與心葉，葉片捲曲皺縮，並分泌蜜露引發煤煙病。", "cucurbit": "群聚嫩葉與生長點，葉片捲曲；會傳播多種瓜類嵌紋病毒。", "citrus": "危害嫩梢使新葉捲曲，並傳播柑橘病毒病害。", "papaya": "直接危害較輕，主要危害是傳播木瓜輪點病毒。", "potato": "群聚葉背與嫩梢，主要危害是傳播馬鈴薯病毒病害。", "strawberry": "群聚新葉與花序，造成新葉捲縮，並傳播草莓病毒。", "goldenberry": "群聚於嫩梢與葉背吸汁，新葉捲縮並沾滿蜜露；也會傳播病毒病。", "chrysanthemum": "菊小長管蚜等群聚在嫩梢、花梗與花苞上吸汁，造成嫩葉捲縮、花朵發育不良，並分泌蜜露。"}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('silverleaf-whitefly', 30, '銀葉粉蝨', 'Silverleaf whitefly', 'Bemisia tabaci（= B. argentifolii）', 'pest', array['tomato', 'cucurbit', 'pepper', 'eggplant', 'crucifer', 'goldenberry']::text[], array['leaf']::text[], array['yellowing', 'honeydew', 'insects', 'silvering']::text[], '設施及夏秋季極常見的刺吸式害蟲，除了吸汁外，還會傳播番茄黃化捲葉病毒等病毒病。', '["成蟲約 1 mm，白色翅、淡黃色身體，停棲時翅呈屋脊狀；輕碰葉片就成群飛起。", "若蟲扁平橢圓，固定在葉背。", "刺吸造成葉片黃化；瓜類（如南瓜）葉片出現銀白化（銀葉症）。", "番茄果實轉色不均；分泌蜜露引起煤煙病。", "傳播番茄黃化捲葉病毒等病毒。"]'::jsonb, '高溫乾燥的夏秋季族群最高，設施內全年都會發生；寄主範圍很廣。', '["使用 50 目以上防蟲網。", "黃色黏紙大量誘殺成蟲。", "清除雜草及前作殘株，育苗場與生產田隔離。", "銀色反光敷蓋可降低成蟲停棲。"]'::jsonb, '["輪用不同作用機制的登記藥劑，重點噴葉背。", "可評估已登記的白殭菌等微生物製劑。", "保護天敵，例如小黑瓢蟲及寄生蜂。"]'::jsonb, '[{"k": "bug", "t": "whitefly", "cap": "成蟲白色翅，停棲時呈屋脊狀"}, {"k": "leaf", "shape": "lobed", "p": "silverleaf", "cap": "瓜類葉片銀白化（銀葉症）"}]'::jsonb, 'Bemisia tabaci', array['tylcv', 'aphids', 'thrips']::text[], '{"tomato": "主要危害是傳播番茄黃化捲葉病毒，少量成蟲就可能造成嚴重損失。", "cucurbit": "南瓜等瓜類葉片呈銀白色（銀葉症），果實色淡；也會傳播病毒。", "crucifer": "群聚葉背吸食，葉片褪色，並分泌蜜露引發煤煙病。", "goldenberry": "葉背聚集大量成蟲與若蟲，蜜露誘發煤煙病；也可能傳播雙生病毒造成葉片黃化捲曲。"}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('thrips', 31, '薊馬', 'Thrips', 'Thrips palmi、Scirtothrips dorsalis、Frankliniella occidentalis 等', 'pest', array['cucurbit', 'pepper', 'eggplant', 'mango', 'grape', 'citrus', 'strawberry', 'goldenberry', 'chrysanthemum']::text[], array['leaf', 'flower', 'fruit']::text[], array['silvering', 'curling', 'cracking', 'insects']::text[], '體型極小、藏在花與嫩芽中的銼吸式害蟲，造成葉片與果皮擦傷，部分種類會傳播病毒。', '["體長約 1 mm，身體細長，黃色或黑褐色，翅緣有長緣毛。", "銼吸葉片與果實表皮，造成銀白色或褐色擦傷痕（銀化、褐化）。", "新葉皺縮捲曲。", "果實表面粗糙、木栓化、畸形（例如芒果、葡萄果皮褐化，茄子果皮擦痕）。", "部分種類會傳播番茄斑點萎凋病毒屬（Orthotospovirus）的病毒。"]'::jsonb, '高溫乾燥時嚴重；蟲體藏在花內、新芽及葉背，不容易防治，繁殖又快。', '["藍色黏紙監測（薊馬偏好藍色）。", "清除雜草，使用防蟲網及銀色敷蓋。", "保護天敵，例如捕植蟎、小黑花椿象。"]'::jsonb, '["輪用登記藥劑，施藥要噴到花與心芽。", "依族群狀況間隔數天連續防治，以打斷世代。"]'::jsonb, '[{"k": "bug", "t": "thrips", "cap": "身體細長，翅緣有長緣毛"}, {"k": "leaf", "p": "silver", "cap": "葉片銀白色或褐色擦痕"}, {"k": "fruit", "fruit": "mango", "p": "scar", "cap": "果皮褐色木栓化擦痕"}]'::jsonb, 'Thrips palmi', array['spider-mites', 'silverleaf-whitefly']::text[], '{"cucurbit": "危害生長點與嫩葉，造成心葉萎縮、葉片皺縮，並會傳播病毒。", "pepper": "新葉向上捲曲、畸形，果實表面出現褐色擦痕與疤痕。", "eggplant": "果實表面出現褐色擦痕，蒂下最明顯，嚴重時果面粗糙。", "mango": "危害花穗與幼果，果實表面出現褐色木栓化擦痕。", "grape": "果粒表面出現褐色擦痕，新梢葉片皺縮。", "citrus": "幼果果蒂周圍出現環狀銀白至褐色疤痕，影響外觀。", "strawberry": "危害花與果實，果面種子周圍褐化、失去光澤。", "goldenberry": "危害嫩葉、花及幼果，葉片出現銀白色擦痕並皺縮，宿萼與果皮留下褐色疤痕。", "chrysanthemum": "危害嫩葉與花朵，葉片出現銀白色擦痕，花瓣出現褐色斑點與畸形，影響乾花品質；部分種類可傳播番茄斑萎病毒。"}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('spider-mites', 32, '葉蟎（紅蜘蛛）', 'Spider mites', 'Tetranychus urticae、Tetranychus kanzawai 等', 'pest', array['strawberry', 'cucurbit', 'papaya', 'eggplant', 'pepper', 'tomato', 'citrus', 'goldenberry', 'chrysanthemum']::text[], array['leaf']::text[], array['webbing', 'yellowing', 'spots', 'insects']::text[], '高溫乾燥時爆發的微小蟎類，群聚葉背吸汁，葉面出現密集褪色小點並結細絲網。', '["體長約 0.5 mm，肉眼看像小點；二點葉蟎身體兩側各有一個深色斑。", "群聚在葉背刺吸，葉面出現密集的黃白色細小斑點（褪色斑）。", "嚴重時葉片黃褐乾枯、落葉。", "族群高時，葉背及葉片之間有細絲網。"]'::jsonb, '高溫乾燥時嚴重，設施及乾季常見；濫用殺蟲劑殺死天敵後容易爆發。繁殖快，容易產生抗藥性。', '["釋放天敵，例如法拉斯捕植蟎、基徵草蛉。", "清除下位老葉及雜草。", "維持適當濕度，避免過度乾燥。", "避免濫用廣效性殺蟲劑。"]'::jsonb, '["使用登記的殺蟎劑，並輪替作用機制（殺蟎劑的抗藥性問題很嚴重）。", "施藥要噴到葉背，並注意藥劑對天敵的影響。"]'::jsonb, '[{"k": "bug", "t": "mite", "cap": "身體兩側各有一個深色斑（二點）"}, {"k": "leaf", "p": "stipple", "cap": "葉面密集黃白小點與細絲"}]'::jsonb, 'Tetranychus urticae', array['thrips']::text[], '{"strawberry": "聚集葉背吸食，葉面先出現白色小點，再轉青銅褐色；高溫乾燥時數量暴增。", "cucurbit": "葉面出現黃白色小點，嚴重時葉片枯黃並結網。", "papaya": "葉片褪色黃化，提早落葉，影響果實發育。", "eggplant": "葉片褪色呈灰白，葉背可見蟎體與細絲。", "pepper": "葉片褪色、捲曲，嚴重時落葉。", "tomato": "葉片褪色黃化，嚴重時植株結網、葉片乾枯。", "citrus": "葉面出現灰白小點並失去光澤，果實表面變灰暗。", "goldenberry": "高溫乾燥時在葉背危害，葉面出現密集黃白色小點，嚴重時葉片黃褐並結細網。", "chrysanthemum": "高溫乾燥時在葉背危害，葉面密生黃白色小點，嚴重時葉片枯黃並結網。"}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('oriental-fruit-fly', 33, '東方果實蠅', 'Oriental fruit fly', 'Bactrocera dorsalis', 'pest', array['mango', 'guava', 'citrus', 'papaya', 'banana']::text[], array['fruit']::text[], array['rot', 'drop', 'insects']::text[], '台灣果樹最重要的害蟲之一，雌蟲在果實內產卵，幼蟲（蛆）在果肉內取食造成腐爛落果。', '["成蟲體長約 7–8 mm，胸背黑色並有一對黃色縱紋，腹部有黑色 T 字形紋。", "雌蟲以產卵管刺入果皮產卵，果面留下小孔（叮痕），周圍變色。", "幼蟲在果肉內取食，造成果實腐爛、提早落果。"]'::jsonb, '全年都會發生，夏季（約 5–10 月）為高峰；寄主多達數百種水果。', '["果實套袋。", "清除落果及爛果（深埋，或裝袋曝曬悶殺），不要任意丟棄。", "全區共同防治效果最好。"]'::jsonb, '["使用甲基丁香油（含殺蟲劑）誘殺雄蟲。", "使用蛋白質水解物誘餌（雌雄蟲都能誘殺）。", "依《植物保護手冊》以登記藥劑點噴或誘餌噴灑。"]'::jsonb, '[{"k": "bug", "t": "fruitfly", "cap": "胸背有黃色縱紋，腹部有黑色 T 字紋"}, {"k": "fruit", "fruit": "mango", "p": "sting", "cap": "果面叮痕與腐爛"}]'::jsonb, 'Bactrocera dorsalis', array['melon-fly']::text[], '{"mango": "果實轉色期起受害最嚴重，產卵孔周圍腐爛、提早落果；建議套袋。", "guava": "果實全年都可能受害，套袋是最有效的防護方法。", "citrus": "產卵孔周圍果皮提早轉色、軟化，造成落果。", "papaya": "主要危害成熟果實，產卵孔流出乳汁，果肉腐爛。", "banana": "主要危害過熟果實，青果較少受害；及早採收可降低損失。"}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('melon-fly', 34, '瓜實蠅', 'Melon fly', 'Zeugodacus cucurbitae（= Bactrocera cucurbitae）', 'pest', array['cucurbit']::text[], array['fruit', 'flower']::text[], array['rot', 'drop', 'insects', 'curling']::text[], '瓜類最主要的果實害蟲，在幼果產卵，幼蟲蛀食果肉造成腐爛畸形。', '["成蟲黃褐色，翅上有褐色帶紋，翅端有褐斑。", "雌蟲在幼果上產卵，果面出現叮痕與流膠。", "幼蟲蛀食果肉，造成腐爛、畸形及落果。"]'::jsonb, '溫暖季節族群高，瓜類開花及結果期最容易受害。', '["幼果套袋。", "清除被害果。", "網室栽培。"]'::jsonb, '["使用克蠅（Cue-lure）誘殺雄蟲。", "使用蛋白質誘餌。", "依《植物保護手冊》施用登記藥劑。"]'::jsonb, '[{"k": "bug", "t": "melonfly", "cap": "翅具褐色帶紋與翅端褐斑"}, {"k": "fruit", "fruit": "cucurbit", "p": "sting", "cap": "幼果產卵叮痕與腐爛"}]'::jsonb, 'Bactrocera cucurbitae', array['oriental-fruit-fly']::text[], '{}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('fall-armyworm', 35, '秋行軍蟲', 'Fall armyworm', 'Spodoptera frugiperda', 'pest', array['corn']::text[], array['leaf', 'fruit']::text[], array['holes', 'insects']::text[], '2019 年入侵台灣的重要害蟲，主要危害玉米心葉與雌穗。', '["幼蟲頭部有明顯的白色倒 Y 字紋。", "腹部末端（第 8 腹節）背面有四個黑點排成正方形。", "危害玉米心葉，留下大量不規則孔洞及濕潤、像鋸木屑的糞便。", "也會鑽蛀雌穗。"]'::jsonb, '高溫期世代短、繁殖快；成蟲遷飛能力強。', '["苗期起定期巡查心葉，早期發現。", "同一地區適期集中播種。", "利用性費洛蒙監測，並清除田間雜草與殘株。"]'::jsonb, '["幼蟲低齡期（心葉期）防治效果最好，藥液要灌入心葉。", "輪用政府公告的登記藥劑，也可使用蘇力菌等生物製劑。"]'::jsonb, '[{"k": "bug", "t": "caterpillar", "color": "#6b5a44", "y": true, "dots": true, "cap": "頭部白色倒 Y 字紋，尾端四個黑點"}, {"k": "leaf", "shape": "grass", "p": "holes", "style": "chew", "cap": "心葉大量不規則孔洞與糞便"}]'::jsonb, 'Spodoptera frugiperda larva', array['spodoptera-litura', 'corn-southern-rust']::text[], '{}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('brown-planthopper', 36, '褐飛蝨', 'Brown planthopper', 'Nilaparvata lugens', 'pest', array['rice']::text[], array['stem', 'whole']::text[], array['yellowing', 'wilting', 'insects', 'honeydew']::text[], '群聚在稻株基部吸汁的害蟲，族群高時造成田間成片枯死（蝨燒）。', '["體長約 3–4 mm，褐色，群聚在稻株基部刺吸。", "族群高時，稻株由下往上黃化枯萎。", "田間出現圓形的倒伏枯死區塊（蝨燒、hopperburn）。", "會傳播草狀矮化病、皺縮矮化病。"]'::jsonb, '高溫多濕時族群高；主要從境外隨氣流遷入。氮肥過多、密植時嚴重。', '["合理施肥，避免氮肥過多。", "適當密植，保持通風。", "選用抗蟲品種。", "巡田時撥開稻叢檢查基部。"]'::jsonb, '["族群增加時施藥，藥液必須噴到稻株基部。", "輪用登記藥劑。"]'::jsonb, '[{"k": "bug", "t": "planthopper", "cap": "群聚在稻株基部"}, {"k": "plant", "state": "hopperburn", "cap": "田間圓形枯死區（蝨燒）"}]'::jsonb, 'Nilaparvata lugens', array['rice-sheath-blight', 'rice-leaffolder']::text[], '{}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('rice-leaffolder', 37, '稻縱捲葉蟲', 'Rice leaffolder', 'Cnaphalocrocis medinalis', 'pest', array['rice']::text[], array['leaf']::text[], array['curling', 'holes', 'insects']::text[], '幼蟲吐絲把稻葉縱向捲成筒狀，躲在裡面啃食葉肉。', '["幼蟲吐絲把葉片縱向捲成筒狀，在裡面啃食葉肉。", "被害葉留下白色條狀表皮，田間可見許多白色捲葉。", "劍葉受害會影響產量。"]'::jsonb, '氮肥過多、葉色濃綠的田區較嚴重，多發生在夏秋季。', '["合理施用氮肥。", "保護天敵，例如寄生蜂、蜘蛛。"]'::jsonb, '["初齡幼蟲期施藥。", "可使用蘇力菌（Bt）等生物製劑。"]'::jsonb, '[{"k": "leaf", "shape": "grass", "p": "rolled", "cap": "葉片縱捲成筒，留下白色條斑"}]'::jsonb, 'Cnaphalocrocis medinalis', array['brown-planthopper']::text[], '{}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('asian-citrus-psyllid', 38, '柑橘木蝨', 'Asian citrus psyllid', 'Diaphorina citri', 'pest', array['citrus']::text[], array['leaf', 'stem']::text[], array['curling', 'honeydew', 'insects']::text[], '柑橘黃龍病的傳播媒介，新梢期是防治關鍵。', '["成蟲約 3 mm，停棲時頭低尾高，身體與枝葉約呈 45 度斜角。", "若蟲黃橙色、扁平，群聚在嫩梢，分泌白色蠟絲。", "新梢捲曲畸形。", "最大的危害是傳播柑橘黃龍病。"]'::jsonb, '新梢抽發期族群激增；七里香（月橘）是重要寄主。', '["統一修剪，讓新梢整齊抽發，方便集中防治。", "移除果園周邊的七里香。", "黃色黏紙監測。"]'::jsonb, '["新梢萌發期（嫩芽剛長出時）施用登記藥劑。", "全區共同防治效果最好。"]'::jsonb, '[{"k": "bug", "t": "psyllid", "cap": "成蟲停棲呈 45 度斜角；若蟲有白色蠟絲"}]'::jsonb, 'Diaphorina citri', array['citrus-hlb']::text[], '{}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('leafminer', 39, '斑潛蠅', 'Leafminers', 'Liriomyza sativae、Liriomyza trifolii 等', 'pest', array['tomato', 'cucurbit', 'crucifer', 'pepper', 'eggplant', 'goldenberry', 'chrysanthemum']::text[], array['leaf']::text[], array['mines', 'insects']::text[], '幼蟲在葉片內潛食，形成白色蛇行隧道。', '["葉片出現白色彎曲的蛇行隧道，隧道內有黑色蟲糞線。", "雌成蟲產卵或取食時，在葉面留下白色小點。", "嚴重時葉片乾枯。"]'::jsonb, '溫暖乾燥時族群高，設施栽培常見。', '["黃色黏紙誘殺成蟲。", "摘除受害葉。", "清除雜草，使用防蟲網。"]'::jsonb, '["輪用登記藥劑。", "保護寄生蜂等天敵。"]'::jsonb, '[{"k": "leaf", "p": "mines", "cap": "白色蛇行隧道，內有黑色蟲糞線"}]'::jsonb, 'Liriomyza leaf mine', array['silverleaf-whitefly']::text[], '{"goldenberry": "葉片出現白色彎曲隧道，幼苗期受害較嚴重，影響光合作用與生長。", "chrysanthemum": "葉片出現白色彎曲隧道，嚴重時葉片乾枯，影響植株生長。"}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('golden-apple-snail', 40, '福壽螺', 'Golden apple snail', 'Pomacea canaliculata', 'pest', array['rice']::text[], array['leaf', 'stem']::text[], array['holes', 'insects']::text[], '外來入侵種，啃食剛插秧的秧苗，造成缺株。', '["螺殼黃褐色至黑褐色。", "在田埂、稻株或水生植物的莖上產下鮮粉紅色卵塊。", "啃食秧苗基部，造成缺株。"]'::jsonb, '田間積水時活動旺盛；插秧後至分蘗初期秧苗幼嫩，最容易受害。', '["插秧後保持淺水或適度排水（淺水時螺的移動與取食受限）。", "進水口設置網罩。", "撿拾螺體並刮除卵塊。", "田中設置集螺溝，並使用較大的秧苗。"]'::jsonb, '["使用已登記的防治資材（例如苦茶粕），並注意對魚類等水生生物的影響。"]'::jsonb, '[{"k": "bug", "t": "snail", "cap": "螺體與鮮粉紅色卵塊"}]'::jsonb, 'Pomacea canaliculata eggs', array['rice-blast']::text[], '{}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('flea-beetle', 41, '黃條葉蚤', 'Striped flea beetle', 'Phyllotreta striolata', 'pest', array['crucifer']::text[], array['leaf', 'root']::text[], array['holes', 'insects']::text[], '十字花科常見的小型甲蟲，成蟲把葉片咬出密集小孔，幼蟲在土中危害根部。', '["成蟲體長約 2 mm，黑色有光澤，翅鞘上各有一條黃色彎曲縱紋；受驚擾就跳走。", "成蟲取食葉片，造成密集的小圓孔（像被散彈打過）。", "幼蟲在土中危害根部，蘿蔔表面出現蟲道與黑斑。"]'::jsonb, '連作十字花科、高溫乾燥時嚴重。', '["與非十字花科作物輪作。", "整地時浸水，淹死土中的幼蟲與蛹。", "網室栽培，使用黃色黏紙。"]'::jsonb, '["依《植物保護手冊》於播種前進行土壤處理，並在苗期施藥。"]'::jsonb, '[{"k": "bug", "t": "flea", "cap": "黑色翅鞘各有一條黃色彎曲縱紋"}, {"k": "leaf", "p": "holes", "style": "shot", "cap": "葉片密集小圓孔"}]'::jsonb, 'Phyllotreta striolata', array['diamondback-moth']::text[], '{}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('epilachna-beetle', 42, '二十八星瓢蟲', '28-spotted ladybird', 'Henosepilachna vigintioctopunctata', 'pest', array['goldenberry', 'eggplant', 'potato', 'tomato']::text[], array['leaf', 'fruit']::text[], array['holes', 'insects']::text[], '植食性瓢蟲，成蟲與幼蟲刮食葉肉，留下網狀或天窗狀食痕，是茄科作物常見害蟲。', '["成蟲半球形，體長約 6–8 mm，橙黃至紅褐色，翅鞘上共有 28 個黑斑，體表有細毛、沒有光澤。", "幼蟲黃色、橢圓形，背上有分枝狀棘刺。", "成蟲與幼蟲在葉背刮食葉肉、只留表皮，形成半透明的條紋狀食痕，之後乾枯破裂成網狀孔洞。", "嚴重時葉片只剩葉脈，也會刮食果實表面。"]'::jsonb, '春季至秋季發生，溫暖時密度高；成蟲可在田邊雜草（如野生茄科植物）與作物殘株中越冬。', '["清除田區周邊的茄科雜草與殘株。", "定期巡田，人工捕殺成蟲並摘除葉背的黃色卵塊。", "網室栽培。"]'::jsonb, '["族群密度高時依《植物保護手冊》選用登記藥劑，著重噴施葉背，並輪替不同作用機制的藥劑。"]'::jsonb, '[{"k": "bug", "t": "ladybird", "cap": "橙褐色翅鞘共 28 個黑斑，體表有細毛"}, {"k": "leaf", "p": "holes", "style": "window", "cap": "刮食葉肉形成天窗狀食痕"}]'::jsonb, 'Henosepilachna vigintioctopunctata', array['flea-beetle', 'spodoptera-litura']::text[], '{"goldenberry": "葉片被刮食成網狀，嫩葉受害較重，也會刮食宿萼。", "eggplant": "茄子最常受害，葉片布滿網狀食痕，果皮被刮食後留下褐色疤痕。", "potato": "葉片被刮食成網狀，嚴重時植株提早枯黃，影響薯塊肥大。"}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('root-knot-nematode', 43, '根瘤線蟲', 'Root-knot nematodes', 'Meloidogyne spp.', 'pest', array['tomato', 'cucurbit', 'pepper', 'eggplant', 'banana', 'papaya', 'guava', 'goldenberry', 'chrysanthemum']::text[], array['root', 'whole']::text[], array['galls', 'wilting', 'stunting', 'yellowing']::text[], '寄生在根部的微小線蟲，根部形成串珠狀瘤腫，地上部生長不良。', '["地上部生長不良、矮化、葉片黃化，高溫時中午萎凋。", "根部形成大小不一的瘤狀腫大，常像串珠。", "與根瘤病不同，線蟲的瘤是根組織本身腫大。", "根系減少，容易引發青枯病、萎凋病等二次感染。"]'::jsonb, '砂質土壤、連作、高溫時嚴重。', '["水旱輪作（淹水）。", "輪作非寄主作物，例如萬壽菊、太陽麻綠肥。", "使用無病苗。", "夏季覆蓋塑膠布進行太陽能消毒，並增施有機質。"]'::jsonb, '["定植前使用登記的土壤處理藥劑或生物製劑。"]'::jsonb, '[{"k": "roots", "type": "knot", "cap": "根部串珠狀瘤腫"}, {"k": "bug", "t": "nematode", "cap": "線蟲（顯微放大示意）"}]'::jsonb, 'Meloidogyne root knot galls', array['clubroot', 'bacterial-wilt']::text[], '{"tomato": "根部形成串珠狀大小腫瘤，植株白天萎凋、生長不良。", "cucurbit": "根部腫瘤明顯，植株黃化矮小、果實小。", "banana": "根部腫大變形，植株生長慢、易倒伏，果串小。", "papaya": "根部腫瘤造成植株生長停滯、葉片黃化。", "guava": "根部腫瘤並伴隨根腐，植株衰弱、葉片黃化提早落葉。", "goldenberry": "根部形成大小不一的根瘤，植株生長衰弱、葉片黃化，並容易併發萎凋病與青枯病。", "chrysanthemum": "根部形成根瘤，植株矮化、葉片黃化，開花數減少。"}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('scale-insects', 44, '介殼蟲', 'Scale insects and mealybugs', '盾介殼蟲科、介殼蟲科、粉介殼蟲科等', 'pest', array['citrus', 'mango', 'papaya', 'guava', 'coconut']::text[], array['leaf', 'stem', 'fruit']::text[], array['honeydew', 'yellowing', 'insects']::text[], '固著在枝葉及果實上刺吸的害蟲，外有蠟殼保護，分泌蜜露誘發煤煙病。', '["蟲體固著在枝條、葉片、果實表面，外覆蠟質介殼，或有白色粉狀蠟（粉介殼蟲）。", "刺吸使枝葉黃化、樹勢衰弱。", "分泌蜜露誘發煤煙病，果實外觀受損。"]'::jsonb, '通風不良、樹冠過密時嚴重；螞蟻會搬運並保護介殼蟲。', '["修剪，保持通風。", "剪除嚴重被害枝。", "防治螞蟻。", "保護天敵（瓢蟲、寄生蜂）。"]'::jsonb, '["若蟲孵化期（還沒形成蠟殼前）施藥效果最好。", "可使用已登記的礦物油（窄域油）。"]'::jsonb, '[{"k": "bug", "t": "scale", "cap": "枝條上的介殼與白色粉介殼蟲"}, {"k": "leaf", "p": "sooty", "cap": "蜜露誘發煤煙病"}]'::jsonb, 'mealybug citrus', array['aphids']::text[], '{"citrus": "固著在葉、枝及果實上吸食，果面留下斑點，並引發煤煙病。", "mango": "葉片與枝條布滿介殼，樹勢衰弱，並引發煤煙病。", "coconut": "椰子盾介殼蟲等群聚在葉背吸汁，葉片出現黃斑並逐漸黃化，嚴重時整片葉枯黃，果實也會被寄生。"}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('coconut-hispine-beetle', 45, '椰子紅胸葉蟲', 'Coconut hispine beetle', 'Brontispa longissima', 'pest', array['coconut']::text[], array['leaf']::text[], array['silvering', 'scorch', 'insects']::text[], '危害椰子等棕櫚科植物的外來害蟲，成蟲與幼蟲躲在未展開的心葉內取食，葉片展開後出現褐色條紋並枯乾，像被火燒過。', '["成蟲體長約 8–10 mm，細長扁平，前胸背板紅褐色、翅鞘黑褐色。", "幼蟲扁平、淡黃白色，尾端有一對鉗狀突起。", "成蟲與幼蟲在未展開的心葉內刮食小葉表皮，留下與葉脈平行的褐色條狀食痕。", "心葉展開後小葉褐化、捲縮乾枯，嚴重時樹冠一片枯褐，幼株生長停滯甚至死亡。"]'::jsonb, '全年發生，高溫乾旱時危害較嚴重；幼齡植株與矮種椰子受害明顯。成蟲飛行能力弱，主要隨帶蟲苗木遠距離傳播。', '["不從發生地區引進帶蟲苗木，新種苗先檢查心葉。", "定期檢查心葉，剪除嚴重受害葉並銷毀。", "可配合釋放寄生蜂等天敵進行生物防治。"]'::jsonb, '["族群密度高時依《植物保護手冊》選用登記藥劑，藥液需噴灌到未展開的心葉內才有效。", "椰子的登記藥劑有限，用藥前請先查詢《植物保護手冊》確認已登記於椰子，並遵守安全採收期。"]'::jsonb, '[{"k": "bug", "t": "hispine", "cap": "成蟲細長扁平，前胸紅褐色、翅鞘黑褐色"}, {"k": "leaf", "shape": "grass", "p": "streak", "cap": "小葉上與葉脈平行的褐色條狀食痕"}]'::jsonb, 'Brontispa longissima', array['red-palm-weevil', 'scale-insects']::text[], '{}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('red-palm-weevil', 46, '紅棕象鼻蟲', 'Red palm weevil', 'Rhynchophorus ferrugineus', 'pest', array['coconut']::text[], array['stem', 'whole']::text[], array['insects', 'wilting', 'rot']::text[], '棕櫚科植物最具毀滅性的害蟲之一，幼蟲在樹幹與生長點內鑽食，外觀不易察覺，發現時植株常已無法挽救。', '["成蟲體長約 3 cm，紅褐色，口吻細長，前胸背板有黑色斑點。", "幼蟲乳白色、無腳、肥大，頭部紅褐色，在樹幹內鑽食。", "樹幹或葉柄基部出現蛀孔，流出褐色黏液並有發酵臭味，可見咬碎的纖維蟲屑；貼近樹幹有時可聽到幼蟲啃食聲。", "心葉黃化枯萎，最後生長點腐爛、樹冠倒塌，植株死亡。"]'::jsonb, '全年發生；修剪葉片、機械傷口及其他害蟲造成的傷口會吸引成蟲產卵。受害株若未處理，會成為周邊植株的蟲源。', '["避免在植株上造成傷口，修剪後保護傷口。", "利用聚集費洛蒙誘蟲器監測及誘殺成蟲。", "定期巡查樹幹與葉柄基部是否有蛀孔、流出黏液。"]'::jsonb, '["嚴重受害株應及早砍除，連同樹幹切碎或銷毀，避免成蟲羽化擴散；必要時向當地農業改良場或防檢機關通報。", "初期受害株可依《植物保護手冊》以登記藥劑處理。", "椰子的登記藥劑有限，用藥前請先查詢《植物保護手冊》確認已登記於椰子，並遵守安全採收期。"]'::jsonb, '[{"k": "bug", "t": "weevil", "cap": "紅褐色成蟲，口吻細長，前胸背板有黑斑"}, {"k": "plant", "state": "crowndie", "cap": "心葉黃化枯萎，最後樹冠倒塌"}]'::jsonb, 'Rhynchophorus ferrugineus', array['coconut-bud-rot', 'coconut-hispine-beetle']::text[], '{}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('def-n', 47, '缺氮（N）', 'Nitrogen deficiency', 'N', 'nutrient', array['*']::text[], array['leaf', 'whole']::text[], array['yellowing', 'stunting']::text[], '最常見的營養缺乏。氮在植物體內容易移動，會由老葉轉移到新葉，所以老葉先均勻黃化。', '["下位老葉先均勻黃化（連葉脈也黃），再逐漸往上發展。", "植株矮小，分蘗或分枝少。", "葉片小而薄。", "提早成熟，產量降低。"]'::jsonb, '砂質土、有機質低、多雨淋洗時容易缺氮；大量施用未腐熟、碳氮比高的有機物（如稻殼、木屑）會造成氮飢餓。', '["依土壤分析及作物需求，分次施肥。", "增施腐熟的有機質。", "種植豆科綠肥。"]'::jsonb, '["追施速效氮肥（例如尿素、硫酸銨）。", "或葉面噴施低濃度尿素（約 0.3–0.5%）。", "不要過量施用：氮過多會徒長，也容易招來病蟲害。"]'::jsonb, '[{"k": "leaf", "p": "chlorosis", "color": "#d9d06a", "tag": "老葉", "cap": "老葉均勻黃化（連葉脈也黃）"}, {"k": "plant", "state": "old", "color": "#d9d06a", "cap": "症狀由下位老葉開始"}]'::jsonb, 'nitrogen deficiency leaves', array['def-s', 'def-mg']::text[], '{"rice": "全田葉色淡黃綠，下位葉先黃；分蘗少、植株矮小，穗數與每穗粒數減少。", "corn": "下位葉由葉尖沿中肋呈 V 字形黃化，再向葉基擴展，最後整葉枯黃。", "tomato": "下位葉均勻黃化、莖細硬，葉背葉脈可能帶紫色；開花少、果實小。", "crucifer": "外葉黃化提早脫落，植株小，結球小而鬆散。", "cucurbit": "老葉黃化、蔓細弱，雌花少，果實小且色淡。", "strawberry": "老葉黃化並轉紅褐色，匍匐莖少、植株小，果實小。", "citrus": "葉片均勻淡黃，新梢短弱、落葉增加，著果少。", "banana": "葉色淡綠，葉柄與葉鞘略帶粉紅色，新葉抽出慢、葉片間距縮短。", "coconut": "全株葉色均勻淡黃，從老葉開始；新葉變小、抽葉速度變慢。"}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('def-p', 48, '缺磷（P）', 'Phosphorus deficiency', 'P', 'nutrient', array['*']::text[], array['leaf', 'whole', 'root']::text[], array['purple', 'stunting']::text[], '植株矮小、葉色暗綠並帶紫紅色，玉米、番茄的幼苗期特別明顯。', '["植株矮小，生長緩慢。", "葉色暗綠，老葉、莖或葉背呈紫紅色（花青素累積，玉米特別明顯）。", "根系發育差。", "開花、結果延遲。"]'::jsonb, '酸性土壤（磷被鐵、鋁固定）或鹼性土壤（磷被鈣固定）容易缺磷；低溫期根部吸收能力差。', '["基肥施用磷肥（例如過磷酸鈣），並施在靠近根群處。", "把土壤 pH 調整到約 6–7。", "增施有機質。"]'::jsonb, '["追施水溶性磷肥，或葉面噴施磷酸二氫鉀。", "低溫期設法提高地溫（例如敷蓋）。"]'::jsonb, '[{"k": "leaf", "p": "purple", "tag": "老葉", "cap": "葉色暗綠，葉緣與葉背帶紫紅色"}, {"k": "plant", "state": "old", "color": "#7b4a8c", "cap": "下位葉先出現"}]'::jsonb, 'phosphorus deficiency corn purple', array['def-n', 'def-k']::text[], '{"rice": "葉色暗綠、葉片直立而狹小，分蘗少，抽穗與成熟延遲。", "corn": "幼株葉尖與葉緣呈紫紅色最明顯，生長緩慢；氣溫低時更常見。", "tomato": "葉背及葉脈呈紫色，植株矮小，開花結果延遲。", "strawberry": "老葉暗綠帶紫紅色，植株生長緩慢、花少。", "citrus": "果皮粗厚、果心大，果汁少、酸度偏高。"}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('def-k', 49, '缺鉀（K）', 'Potassium deficiency', 'K', 'nutrient', array['*']::text[], array['leaf', 'fruit', 'stem']::text[], array['scorch', 'yellowing', 'spots']::text[], '老葉的葉緣、葉尖先黃化再焦枯，果實品質變差，莖稈也容易倒伏。', '["下位老葉的葉緣與葉尖先黃化，再變成褐色焦枯，葉片中央仍保持綠色。", "葉片可能出現褐色小斑點。", "莖稈細弱，容易倒伏。", "果實小，著色與糖度差（例如番茄轉色不均）。"]'::jsonb, '砂質土、多雨淋洗時容易缺鉀；收穫量大會帶走大量鉀；過量施用鈣、鎂會產生拮抗作用。', '["依土壤分析施用鉀肥（例如氯化鉀、硫酸鉀）。", "結果期增加施用量。"]'::jsonb, '["追施鉀肥，或葉面噴施硫酸鉀、磷酸二氫鉀。"]'::jsonb, '[{"k": "leaf", "p": "scorch", "tag": "老葉", "cap": "葉緣、葉尖黃化後焦枯"}, {"k": "plant", "state": "old", "color": "#b98a3a", "cap": "下位老葉先發生"}]'::jsonb, 'potassium deficiency leaf', array['def-mg', 'def-ca', 'early-blight']::text[], '{"rice": "下位葉葉尖及葉緣出現褐色小斑點並焦枯（赤枯），易倒伏，病害增加。", "corn": "下位葉葉緣焦枯，莖稈軟弱易倒伏，果穗末端結實不良。", "potato": "老葉暗綠帶青銅色光澤，葉緣焦枯，薯塊小、品質差。", "tomato": "老葉葉緣焦枯；果實著色不均（綠肩、斑駁著色），風味淡。", "cucurbit": "老葉葉緣黃化焦枯，果實膨大不良，常出現尾部細小的畸形瓜。", "strawberry": "老葉葉緣焦枯，果實偏軟、甜度與風味不足。", "citrus": "果實小、果皮薄容易裂果，葉片捲曲皺縮。", "banana": "老葉葉尖迅速黃化轉橙褐色並向下彎折，果串小、果指短。", "grape": "夏季老葉葉緣焦枯，葉面變暗紫褐色，果粒著色差、糖度低。", "coconut": "老葉先出現黃橙色斑點並由小葉尖端焦枯，下層葉片提早枯垂；結果數減少、果實變小且容易落果。椰子需鉀量很高。"}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('def-mg', 50, '缺鎂（Mg）', 'Magnesium deficiency', 'Mg', 'nutrient', array['*']::text[], array['leaf']::text[], array['yellowing']::text[], '老葉葉脈間黃化，葉脈保持綠色，形成明顯的綠色網紋。結果量大時常見。', '["下位老葉的葉脈之間黃化，葉脈保持綠色，形成明顯的綠色網紋（魚骨狀）。", "嚴重時黃化部位轉為紅褐色或壞死。", "柑橘葉片基部常留下倒 V 字形的綠色區域。"]'::jsonb, '酸性砂質土容易缺鎂；大量施用鉀肥或銨態氮會產生拮抗；結果量大時養分被果實大量消耗。', '["酸性土壤施用苦土石灰（白雲石粉）。", "平衡施用鉀肥，避免過量。"]'::jsonb, '["葉面噴施硫酸鎂（約 1–2%），連續數次。", "土壤施用硫酸鎂。"]'::jsonb, '[{"k": "leaf", "p": "interveinal", "wide": true, "tag": "老葉", "cap": "葉脈間黃化，葉脈保持綠色"}, {"k": "plant", "state": "old", "color": "#d6cf55", "cap": "下位老葉先發生"}]'::jsonb, 'magnesium deficiency leaf', array['def-fe', 'def-mn', 'def-k', 'def-n']::text[], '{"corn": "下位葉葉脈間呈黃白色條紋，葉脈保持綠色。", "tomato": "下位葉葉脈間黃化，結果多、果實膨大期最常出現。", "cucurbit": "老葉葉脈間黃化，從葉緣向內擴展，結果多的植株最明顯。", "citrus": "結果枝的老葉自中肋兩側黃化，葉基殘留倒 V 字形綠色區塊；結果多的枝條最嚴重。", "banana": "老葉葉緣向中肋方向黃化，中肋兩側保持綠色，葉柄可能出現紫色斑駁。", "grape": "老葉葉脈間黃化（白色品種）或轉紅紫色（紅、黑色品種），葉脈保持綠色。", "coconut": "老葉小葉先端黃化，靠近中軸的部分仍保持綠色，界線明顯；常見於砂質及多雨淋洗的土壤。"}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('def-ca', 51, '缺鈣（Ca）', 'Calcium deficiency', 'Ca', 'nutrient', array['*']::text[], array['fruit', 'leaf']::text[], array['rot', 'scorch', 'curling']::text[], '鈣在植物體內不易移動，症狀出現在果實與新葉，例如番茄尾腐病、甘藍心腐。', '["新生組織先受害（鈣不易移動）。", "番茄、甜椒果實臍部（花蒂端）先出現水浸狀，再變黑褐色凹陷（尾腐病）。", "甘藍、白菜、萵苣心葉的葉緣褐變焦枯（心腐、緣腐）。", "生長點萎縮。"]'::jsonb, '土壤缺鈣常常不是主因，多半是水分供應不均（乾濕變化大）、高溫蒸散太快，或銨態氮、鉀過多產生拮抗，使鈣無法送到果實與心葉；根系受損也會造成。', '["保持土壤水分穩定（敷蓋、滴灌）。", "酸性土壤施用石灰。", "避免過量施用銨態氮與鉀肥。", "設施注意通風，調節溫濕度。"]'::jsonb, '["果實肥大初期葉面噴施鈣劑（例如氯化鈣、硝酸鈣），並噴到果實；注意濃度，避免藥害。", "摘除受害果。"]'::jsonb, '[{"k": "fruit", "fruit": "tomato", "p": "blossom-end", "cap": "番茄果實臍部黑褐凹陷（尾腐）"}, {"k": "leaf", "p": "scorch", "tag": "新葉", "cap": "心葉葉緣焦枯（緣腐）"}]'::jsonb, 'blossom end rot tomato', array['def-b', 'def-k']::text[], '{"tomato": "果實尻腐病：果頂（花落處）出現水浸狀褐黑色凹陷，乾旱或灌水不均時多發。", "pepper": "果實下半部或側面出現灰白至褐色凹陷乾斑（尻腐），高溫乾旱期常見。", "crucifer": "結球白菜、甘藍內部葉緣褐變焦枯（心腐、緣腐），外觀正常，切開才看得到。", "cucurbit": "西瓜等果實尾部凹陷黑腐（尻腐），新葉邊緣枯捲。", "potato": "薯塊內部出現褐斑或空心，頂芽壞死。", "strawberry": "新葉葉尖焦枯、皺縮（葉燒），花萼尖端褐變；高溫、蒸散旺盛或濕度過高時常見。", "mango": "果頂果肉提早軟化、呈水浸狀（軟鼻），與果實鈣含量偏低有關。", "goldenberry": "果實容易裂果，新葉捲曲、生長點受損；土壤乾濕變化劇烈時更明顯。"}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('def-fe', 52, '缺鐵（Fe）', 'Iron deficiency', 'Fe', 'nutrient', array['*']::text[], array['leaf']::text[], array['yellowing']::text[], '鹼性土壤常見，新葉葉脈間黃白化，葉脈保持綠色呈細網狀。', '["新葉先在葉脈之間黃化，葉脈保持綠色，呈細網狀。", "嚴重時整片新葉變成黃白色。", "老葉通常正常。"]'::jsonb, '鹼性或石灰質土壤（pH 約 7.5 以上）中鐵的溶解度低；排水不良、磷肥過量、錳過多時也會發生。柑橘、藍莓等常見。', '["改良土壤酸鹼值（例如施用硫磺粉、酸性有機質）。", "改善排水。", "選用耐鹼砧木。"]'::jsonb, '["葉面噴施螯合鐵（例如 Fe-EDTA），連續數次。", "鹼性土壤的土施宜選用 Fe-EDDHA。"]'::jsonb, '[{"k": "leaf", "p": "interveinal", "pale": true, "tag": "新葉", "cap": "新葉葉脈間黃白化，葉脈呈細綠網紋"}, {"k": "plant", "state": "young", "color": "#ece79a", "cap": "上位新葉先發生"}]'::jsonb, 'iron chlorosis leaf', array['def-mn', 'def-mg', 'def-zn']::text[], '{"rice": "旱田或鹼性土的秧苗，新葉黃白化並呈條紋，生長停滯。", "strawberry": "新葉黃白化、葉脈保持綠色；土壤偏鹼、過濕或排水不良時常見。", "citrus": "新葉葉脈間黃白化、葉脈呈綠色網紋，鹼性或石灰質土壤最常見。", "grape": "石灰質土壤上新梢葉片黃白化，嚴重時葉緣焦枯、果房發育不良。", "mango": "新梢葉片黃白化，鹼性土或根部受損時較常見。"}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('def-b', 53, '缺硼（B）', 'Boron deficiency', 'B', 'nutrient', array['*']::text[], array['leaf', 'fruit', 'stem', 'flower']::text[], array['cracking', 'curling', 'rot', 'stunting', 'drop']::text[], '生長點與生殖器官最先受害，造成莖中空、落花、裂果與畸形果。', '["生長點萎縮壞死，新葉畸形、變厚變脆。", "花椰菜、甘藍的莖部中空褐變（空心莖）；蘿蔔褐心。", "落花、結果不良。", "果實龜裂、畸形（例如木瓜凹凸果、柑橘果皮硬化）。"]'::jsonb, '砂質土、多雨淋洗或乾旱時容易缺硼；大量施用石灰使 pH 升高也會造成。', '["基肥適量施用硼砂或硼酸鹽。", "注意：硼的適量範圍很窄，過量容易中毒。"]'::jsonb, '["開花前後葉面噴施硼酸或硼砂（約 0.1–0.2%）。", "千萬不要過量。"]'::jsonb, '[{"k": "plant", "state": "tipdie", "cap": "生長點萎縮壞死"}, {"k": "fruit", "fruit": "tomato", "p": "crack", "cap": "果實龜裂、畸形"}]'::jsonb, 'boron deficiency', array['def-ca', 'def-zn']::text[], '{"corn": "果穗結實不完整，穗軸上出現空粒或不規則排列。", "tomato": "生長點壞死、莖節縮短，果實表面龜裂或木栓化。", "crucifer": "花椰菜花球褐變、莖中空（空心莖），蘿蔔根部內部褐心。", "strawberry": "新葉皺縮畸形、葉尖焦枯，果實小而畸形、種子少。", "citrus": "果皮增厚硬化、果實畸形，果皮與果心有膠狀褐斑。", "grape": "結實不良，同一串果粒大小不一（大小粒），新梢節間短。", "papaya": "果實表面凹凸不平、呈瘤狀畸形，果肉中常有乳汁凝結的硬塊，容易落果。", "goldenberry": "裂果與畸形果增加，新梢生長點枯死、節間縮短。", "coconut": "新抽出的葉片小葉黏連不展開、皺縮或呈鉤狀（鉤葉），嚴重時心葉畸形、結果減少。"}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('def-zn', 54, '缺鋅（Zn）', 'Zinc deficiency', 'Zn', 'nutrient', array['*']::text[], array['leaf', 'whole']::text[], array['yellowing', 'stunting', 'mosaic', 'curling']::text[], '新葉小而窄、節間縮短呈簇生（小葉病），葉脈間黃化斑駁。', '["新葉小而窄，節間縮短，呈簇生狀（小葉病、簇葉病）。", "葉脈間黃化斑駁。", "玉米新葉基部出現白色寬帶狀條紋（白芽病）。", "柑橘葉片黃綠斑駁；缺鋅斑駁左右對稱，與黃龍病的不對稱斑駁不同。"]'::jsonb, '鹼性土、大量施用磷肥（磷與鋅拮抗）、表土流失、低溫時容易發生。', '["避免過量施用磷肥。", "基肥施用硫酸鋅。"]'::jsonb, '["葉面噴施硫酸鋅（約 0.2–0.5%）或螯合鋅。"]'::jsonb, '[{"k": "plant", "state": "rosette", "cap": "新葉小、節間短，呈簇生狀"}, {"k": "leaf", "p": "interveinal", "mottled": true, "tag": "新葉", "cap": "葉脈間黃化斑駁（左右對稱）"}]'::jsonb, 'zinc deficiency leaf', array['citrus-hlb', 'def-fe', 'def-mn']::text[], '{"rice": "插秧後 2～4 週下位葉出現褐色斑點，植株矮化、分蘗停滯（俗稱稻縮葉）。", "corn": "幼株新葉基部兩側出現白至淡黃色寬條紋（白芽病），節間短。", "citrus": "新梢葉片小而尖、葉脈間黃化呈斑葉（小葉病），節間縮短、枝條叢生。", "mango": "新梢小葉叢生、節間縮短，葉片小而厚。"}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('def-mn', 55, '缺錳（Mn）', 'Manganese deficiency', 'Mn', 'nutrient', array['*']::text[], array['leaf']::text[], array['yellowing', 'spots']::text[], '新葉或中位葉葉脈間淡黃化，葉脈兩旁保留綠帶，界線較模糊。', '["新葉或中位葉出現葉脈間淡黃化，葉脈及葉脈兩旁保留綠色帶。", "斑駁的界線比缺鐵模糊。", "有時出現細小的褐色壞死斑點。"]'::jsonb, '鹼性土、有機質過多、過量施用石灰時容易發生。', '["避免過量施用石灰。", "維持適當的土壤酸鹼值。"]'::jsonb, '["葉面噴施硫酸錳（約 0.2–0.3%）。"]'::jsonb, '[{"k": "leaf", "p": "interveinal", "soft": true, "tag": "新葉", "cap": "葉脈間淡黃化，葉脈兩旁保留綠帶"}]'::jsonb, 'manganese deficiency leaf', array['def-fe', 'def-mg', 'def-zn']::text[], '{"citrus": "新葉葉脈間淡綠，葉脈兩側保留較寬的深綠帶；黃化程度比缺鐵輕。"}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
insert into public.issues (id, sort, name, en, sci, type, crops, parts, tags, summary, symptoms, conditions, prevention, control, illus, photo_query, related, crop_notes) values ('def-s', 56, '缺硫（S）', 'Sulfur deficiency', 'S', 'nutrient', array['*']::text[], array['leaf', 'whole']::text[], array['yellowing', 'stunting']::text[], '新葉均勻黃化，外觀類似缺氮，但缺氮從老葉開始，缺硫從新葉開始。', '["新葉先均勻黃化（包括葉脈）。", "與缺氮相似，但缺氮先出現在老葉。", "植株矮小。", "十字花科、蔥蒜類需硫量高，較容易出現。"]'::jsonb, '砂質土、有機質少時容易缺硫；長期只施用不含硫的高濃度化學肥料也會造成。', '["施用含硫肥料，例如硫酸銨、硫酸鉀、石膏。", "增施有機質。"]'::jsonb, '["追施硫酸銨或硫酸鉀。"]'::jsonb, '[{"k": "leaf", "p": "chlorosis", "color": "#e0d97a", "tag": "新葉", "cap": "新葉均勻黃化"}, {"k": "plant", "state": "young", "color": "#e0d97a", "cap": "上位新葉先發生"}]'::jsonb, 'sulfur deficiency plant', array['def-n']::text[], '{"rice": "全株淡黃，新葉黃化較明顯，與缺氮相似但新葉先黃。", "crucifer": "十字花科需硫量高，缺乏時新葉黃化、葉片變小，葉背可能帶紫紅色。", "corn": "新葉淡黃並出現條紋，植株生長遲緩。"}'::jsonb) on conflict (id) do update set sort = excluded.sort, name = excluded.name, en = excluded.en, sci = excluded.sci, type = excluded.type, crops = excluded.crops, parts = excluded.parts, tags = excluded.tags, summary = excluded.summary, symptoms = excluded.symptoms, conditions = excluded.conditions, prevention = excluded.prevention, control = excluded.control, illus = excluded.illus, photo_query = excluded.photo_query, related = excluded.related, crop_notes = excluded.crop_notes, updated_at = now();
